{
  "name": "FINKI Tutors",
  "description": "A comprehensive online learning platform for FINKI students featuring course bookings, flexible pricing, gamified progress tracking, and AI-powered tutoring."
}

export interface Professor {
  id: string;
  name: string;
  avatar: string;
  specialty: string;
  rating: number;
}

export interface Lecture {
  id: string;
  title: string;
  date: string; // ISO date string
  duration: number; // minutes
}

export interface Course {
  id: string;
  title: string;
  code: string; // e.g., "CSE101"
  description: string;
  professorId: string;
  image: string;
  lectures: Lecture[];
  priceFull: number; // 6000
  priceSingle: number; // 750
}

export interface Achievement {
  id: string;
  title: string;
  description: string;
  icon: string;
  unlocked: boolean;
}

export interface User {
  id: string;
  name: string;
  email: string;
  xp: number;
  level: number;
  credits: number; // Currency or subscription status
  subscriptionTier: 'free' | 'pro';
  bookedLectures: string[]; // IDs of booked lectures
  purchasedCourses: string[]; // IDs of full courses
  achievements: Achievement[];
}

export type BookingType = 'single' | 'full';

import { GoogleGenAI } from "@google/genai";

// Initialize the client.
// Note: In a real environment, ensure process.env.API_KEY is set.
// For this demo, we will handle missing keys gracefully in the UI.
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export const chatWithGemini = async (message: string, history: string[] = []) => {
  if (!apiKey) {
    // Fallback for demo purposes if no API key is present
    return new Promise<string>((resolve) => {
      setTimeout(() => {
        resolve("I'm the FINKI AI Tutor! It seems my API key is missing, but I'm here to help you study Algorithms, Calculus, and more once fully configured.");
      }, 1000);
    });
  }

  try {
    const model = 'gemini-2.5-flash-latest'; // Using Flash for speed/efficiency in a chat context
    const response = await ai.models.generateContent({
      model: model,
      contents: message,
      config: {
        systemInstruction: "You are a helpful, encouraging, and knowledgeable AI tutor for FINKI (Faculty of Computer Science and Engineering in Macedonia). You help students understand computer science topics, math, and programming. Keep answers concise, academic but accessible.",
      }
    });

    return response.text || "I couldn't generate a response. Please try again.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Sorry, I'm having trouble connecting to the FINKI knowledge base right now.";
  }
};

