import React, { useState } from 'react';
import { Course, BookingType } from '../types';
import { X, Calendar, Check, CreditCard, AlertCircle } from 'lucide-react';

interface BookingModalProps {
  course: Course | null;
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (bookingDetails: any) => void;
}

export const BookingModal: React.FC<BookingModalProps> = ({ course, isOpen, onClose, onConfirm }) => {
  const [bookingType, setBookingType] = useState<BookingType>('full');
  const [selectedLecture, setSelectedLecture] = useState<string>('');
  const [step, setStep] = useState(1);

  if (!isOpen || !course) return null;

  const total = bookingType === 'full' ? course.priceFull : course.priceSingle;

  const handleConfirm = () => {
    onConfirm({
      courseId: course.id,
      type: bookingType,
      lectureId: bookingType === 'single' ? selectedLecture : 'all',
      price: total
    });
    setStep(1); // Reset
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto">
      <div className="flex items-center justify-center min-h-screen px-4 text-center">
        <div className="fixed inset-0 bg-gray-500 bg-opacity-75 transition-opacity" onClick={onClose}></div>

        <div className="inline-block w-full max-w-lg p-6 my-8 overflow-hidden text-left align-middle transition-all transform bg-white shadow-xl rounded-2xl">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold text-gray-900">Book {course.title}</h3>
            <button onClick={onClose} className="text-gray-400 hover:text-gray-500">
              <X className="h-6 w-6" />
            </button>
          </div>

          {step === 1 && (
            <div className="space-y-6">
              {/* Option 1: Full Course */}
              <div 
                onClick={() => setBookingType('full')}
                className={`relative p-4 rounded-xl border-2 cursor-pointer transition-all ${bookingType === 'full' ? 'border-indigo-600 bg-indigo-50' : 'border-gray-200 hover:border-indigo-200'}`}
              >
                <div className="flex justify-between items-center">
                  <div>
                    <h4 className="font-bold text-indigo-900">Full Course Bundle</h4>
                    <p className="text-sm text-indigo-700/80">Access to all 10 lectures</p>
                  </div>
                  <div className="text-right">
                    <span className="block text-xl font-bold text-indigo-600">{course.priceFull} MKD</span>
                    <span className="text-xs text-green-600 font-medium">Best Value</span>
                  </div>
                </div>
                {bookingType === 'full' && <div className="absolute top-2 right-2"><Check className="h-4 w-4 text-indigo-600" /></div>}
              </div>

              {/* Option 2: Single Lecture */}
              <div 
                onClick={() => setBookingType('single')}
                className={`relative p-4 rounded-xl border-2 cursor-pointer transition-all ${bookingType === 'single' ? 'border-indigo-600 bg-indigo-50' : 'border-gray-200 hover:border-indigo-200'}`}
              >
                <div className="flex justify-between items-center">
                  <div>
                    <h4 className="font-bold text-gray-900">Single Lecture</h4>
                    <p className="text-sm text-gray-500">Specific topic focus</p>
                  </div>
                  <div className="text-right">
                    <span className="block text-xl font-bold text-gray-900">{course.priceSingle} MKD</span>
                    <span className="text-xs text-gray-400">per session</span>
                  </div>
                </div>
                 {bookingType === 'single' && <div className="absolute top-2 right-2"><Check className="h-4 w-4 text-indigo-600" /></div>}
              </div>

              {bookingType === 'single' && (
                <div className="mt-4 animate-fadeIn">
                  <label className="block text-sm font-medium text-gray-700 mb-2">Select a Lecture</label>
                  <select 
                    value={selectedLecture}
                    onChange={(e) => setSelectedLecture(e.target.value)}
                    className="block w-full pl-3 pr-10 py-2 text-base border-gray-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-md border"
                  >
                    <option value="">-- Choose a topic --</option>
                    {course.lectures.map(l => (
                      <option key={l.id} value={l.id}>{l.title} - {new Date(l.date).toLocaleDateString()}</option>
                    ))}
                  </select>
                </div>
              )}

              <div className="mt-6">
                <button
                  disabled={bookingType === 'single' && !selectedLecture}
                  onClick={() => setStep(2)}
                  className="w-full bg-indigo-600 text-white py-3 rounded-xl font-semibold hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                  Continue to Payment
                </button>
              </div>
            </div>
          )}

          {step === 2 && (
            <div className="space-y-6">
              <div className="bg-gray-50 p-4 rounded-lg flex items-start gap-3">
                <AlertCircle className="h-5 w-5 text-indigo-500 flex-shrink-0 mt-0.5" />
                <p className="text-sm text-gray-600">
                  You are booking <strong>{bookingType === 'full' ? 'Full Course' : 'Single Lecture'}</strong> for <span className="font-bold text-gray-900">{total} MKD</span>.
                </p>
              </div>

              <div className="space-y-4">
                 <div className="flex flex-col gap-2">
                    <label className="text-sm font-medium text-gray-700">Cardholder Name</label>
                    <input type="text" className="w-full border border-gray-300 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 focus:outline-none" placeholder="Marko Markovski" />
                 </div>
                 <div className="flex flex-col gap-2">
                    <label className="text-sm font-medium text-gray-700">Card Number</label>
                    <div className="relative">
                        <CreditCard className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
                        <input type="text" className="w-full border border-gray-300 rounded-lg p-2.5 pl-10 focus:ring-2 focus:ring-indigo-500 focus:outline-none" placeholder="0000 0000 0000 0000" />
                    </div>
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="flex flex-col gap-2">
                        <label className="text-sm font-medium text-gray-700">Expiry</label>
                        <input type="text" className="w-full border border-gray-300 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 focus:outline-none" placeholder="MM/YY" />
                    </div>
                    <div className="flex flex-col gap-2">
                        <label className="text-sm font-medium text-gray-700">CVC</label>
                        <input type="text" className="w-full border border-gray-300 rounded-lg p-2.5 focus:ring-2 focus:ring-indigo-500 focus:outline-none" placeholder="123" />
                    </div>
                 </div>
              </div>

              <div className="flex gap-3 mt-6">
                <button onClick={() => setStep(1)} className="flex-1 py-3 border border-gray-300 text-gray-700 rounded-xl font-medium hover:bg-gray-50">Back</button>
                <button onClick={handleConfirm} className="flex-1 bg-indigo-600 text-white py-3 rounded-xl font-bold hover:bg-indigo-700 shadow-lg shadow-indigo-200">
                  Pay {total} MKD
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { User, Achievement } from '../types';
import { Trophy, Flame, Star, Zap, MessageSquare, Send } from 'lucide-react';
import { chatWithGemini } from '../services/geminiService';

export const XPBar: React.FC<{ user: User }> = ({ user }) => {
  const nextLevelXp = user.level * 1000;
  const progress = (user.xp / nextLevelXp) * 100;

  return (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
      <div className="flex justify-between items-end mb-2">
        <div>
          <span className="text-sm font-medium text-gray-500 uppercase tracking-wider">Current Level</span>
          <div className="text-3xl font-bold text-indigo-600">Lvl {user.level}</div>
        </div>
        <div className="text-right">
          <span className="text-sm font-medium text-gray-600">{user.xp} / {nextLevelXp} XP</span>
        </div>
      </div>
      <div className="h-3 bg-gray-100 rounded-full overflow-hidden">
        <div className="h-full bg-gradient-to-r from-indigo-500 to-purple-500 transition-all duration-1000" style={{ width: `${progress}%` }}></div>
      </div>
      <p className="mt-3 text-xs text-gray-400">Earn {nextLevelXp - user.xp} more XP to reach Level {user.level + 1}</p>
    </div>
  );
};

export const AchievementBadge: React.FC<{ achievement: Achievement }> = ({ achievement }) => {
  const IconMap: any = {
    'graduation-cap': Star,
    'code': Zap,
    'calculator': Trophy,
    'flame': Flame
  };
  const Icon = IconMap[achievement.icon] || Star;

  return (
    <div className={`p-4 rounded-xl border flex items-center gap-4 ${achievement.unlocked ? 'bg-white border-gray-100 shadow-sm' : 'bg-gray-50 border-dashed border-gray-200 opacity-60'}`}>
      <div className={`p-3 rounded-full ${achievement.unlocked ? 'bg-yellow-100 text-yellow-600' : 'bg-gray-200 text-gray-400'}`}>
        <Icon className="h-6 w-6" />
      </div>
      <div>
        <h4 className={`font-bold ${achievement.unlocked ? 'text-gray-900' : 'text-gray-500'}`}>{achievement.title}</h4>
        <p className="text-xs text-gray-500">{achievement.description}</p>
      </div>
    </div>
  );
};

export const AiTutor: React.FC = () => {
  const [messages, setMessages] = useState<{role: 'user'|'ai', text: string}[]>([
    {role: 'ai', text: 'Hi! I am your FINKI AI Tutor. Ask me anything about your subjects!'}
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSend = async () => {
    if(!input.trim()) return;

    const userMsg = input;
    setMessages(prev => [...prev, {role: 'user', text: userMsg}]);
    setInput('');
    setLoading(true);

    const response = await chatWithGemini(userMsg);

    setMessages(prev => [...prev, {role: 'ai', text: response}]);
    setLoading(false);
  };

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden flex flex-col h-[500px]">
      <div className="p-4 border-b border-gray-100 bg-gradient-to-r from-indigo-600 to-purple-600 text-white flex justify-between items-center">
        <div className="flex items-center gap-2">
            <MessageSquare className="h-5 w-5" />
            <h3 className="font-bold">AI Tutor</h3>
        </div>
        <span className="text-xs bg-white/20 px-2 py-0.5 rounded text-white/90">Powered by Gemini</span>
      </div>

      <div className="flex-1 p-4 overflow-y-auto space-y-4 bg-gray-50/50">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] p-3 rounded-2xl text-sm ${
              m.role === 'user' 
              ? 'bg-indigo-600 text-white rounded-br-none' 
              : 'bg-white border border-gray-200 text-gray-800 rounded-bl-none shadow-sm'
            }`}>
              {m.text}
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex justify-start">
             <div className="bg-white border border-gray-200 p-3 rounded-2xl rounded-bl-none shadow-sm">
                <div className="flex gap-1">
                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-75"></div>
                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-150"></div>
                </div>
             </div>
          </div>
        )}
      </div>

      <div className="p-3 bg-white border-t border-gray-100">
        <div className="relative">
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Explain recursion..."
            className="w-full pl-4 pr-12 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white transition-all"
          />
          <button 
            onClick={handleSend}
            disabled={loading}
            className="absolute right-2 top-2 p-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 transition-colors"
          >
            <Send className="h-4 w-4" />
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { COURSES } from '../constants';
import { CourseCard } from '../components/CourseCard';
import { BookingModal } from '../components/BookingModal';
import { Course } from '../types';
import { Search } from 'lucide-react';

export const CoursesPage: React.FC = () => {
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const filteredCourses = COURSES.filter(c => 
    c.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
    c.code.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-gray-50 py-12">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">Available Courses</h1>
            <p className="mt-2 text-gray-600">Select a subject to view details and professors.</p>
          </div>

          <div className="relative">
            <Search className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
            <input 
              type="text" 
              placeholder="Search subjects..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-10 pr-4 py-2.5 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500 w-full md:w-64"
            />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {filteredCourses.map(course => (
            <CourseCard 
              key={course.id} 
              course={course} 
              onBook={setSelectedCourse} 
            />
          ))}
        </div>

        {filteredCourses.length === 0 && (
          <div className="text-center py-20">
            <p className="text-gray-500">No courses found matching your search.</p>
          </div>
        )}

        <BookingModal 
          course={selectedCourse}
          isOpen={!!selectedCourse}
          onClose={() => setSelectedCourse(null)}
          onConfirm={(details) => {
            console.log("Booking confirmed:", details);
            alert(`Booking Successful for ${details.price} MKD!`);
            setSelectedCourse(null);
          }}
        />
      </div>
    </div>
  );
};

