import React, { useState } from 'react';
import { Course, BookingType, Lecture } from '../types';
import { X, Check, Copy, Phone, Wallet, Calendar, Info } from 'lucide-react';

interface BookingModalProps {
  course: Course | null;
  isOpen: boolean;
  onClose: () => void;
  bookingType: BookingType;
  selectedLectureId?: string;
  price: number;
}

export const BookingModal: React.FC<BookingModalProps> = ({ 
  course, 
  isOpen, 
  onClose, 
  bookingType, 
  selectedLectureId, 
  price 
}) => {
  const [copied, setCopied] = useState(false);

  if (!isOpen || !course) return null;

  const phoneNumber = "+389 71 555 999";

  const handleCopy = () => {
    navigator.clipboard.writeText(phoneNumber);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const selectedLecture = course.lectures.find(l => l.id === selectedLectureId);

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto">
      <div className="flex items-center justify-center min-h-screen px-4 text-center">
        <div className="fixed inset-0 bg-gray-900/60 backdrop-blur-sm transition-opacity" onClick={onClose}></div>

        <div className="inline-block w-full max-w-md p-6 my-8 overflow-hidden text-left align-middle transition-all transform bg-white shadow-2xl rounded-2xl border border-gray-100">

          {/* Header */}
          <div className="flex justify-between items-start mb-6">
            <div>
              <h3 className="text-xl font-bold text-gray-900">Booking Confirmation</h3>
              <p className="text-sm text-gray-500 mt-1">Please review your order details</p>
            </div>
            <button onClick={onClose} className="p-1 rounded-full hover:bg-gray-100 transition-colors">
              <X className="h-6 w-6 text-gray-400" />
            </button>
          </div>

          {/* Order Summary */}
          <div className="bg-gray-50 rounded-xl p-4 mb-6 border border-gray-100">
            <h4 className="font-semibold text-gray-900 mb-2">{course.title}</h4>
            <div className="flex items-center gap-2 text-sm text-gray-600 mb-1">
              <span className={`px-2 py-0.5 rounded text-xs font-bold uppercase ${bookingType === 'full' ? 'bg-indigo-100 text-indigo-700' : 'bg-blue-100 text-blue-700'}`}>
                {bookingType === 'full' ? 'Full Course' : 'Single Lecture'}
              </span>
              {bookingType === 'single' && selectedLecture && (
                <span className="truncate max-w-[200px]">- {selectedLecture.title}</span>
              )}
            </div>
            <div className="mt-3 pt-3 border-t border-gray-200 flex justify-between items-center">
              <span className="text-gray-600 font-medium">Total Amount</span>
              <span className="text-2xl font-bold text-gray-900">{price} MKD</span>
            </div>
          </div>

          {/* Cash Only Notice */}
          <div className="mb-6">
            <div className="flex items-center gap-2 mb-3">
              <div className="bg-green-100 p-2 rounded-lg">
                <Wallet className="h-5 w-5 text-green-600" />
              </div>
              <h4 className="font-bold text-gray-900">Payment Method: Cash Only</h4>
            </div>
            <p className="text-sm text-gray-600 leading-relaxed bg-yellow-50 p-3 rounded-lg border border-yellow-100 text-yellow-800">
              <Info className="h-4 w-4 inline mr-1 mb-0.5" />
              To finalize your booking, please pay in cash at our administrative office or contact the professor directly.
            </p>
          </div>

          {/* Contact Section */}
          <div className="mb-8">
            <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">
              Contact for Appointment
            </label>
            <button 
              onClick={handleCopy}
              className="w-full flex items-center justify-between p-4 bg-slate-900 hover:bg-slate-800 text-white rounded-xl transition-all group active:scale-[0.98]"
            >
              <div className="flex items-center gap-3">
                <Phone className="h-5 w-5 text-indigo-400" />
                <span className="text-lg font-mono font-medium tracking-wide">{phoneNumber}</span>
              </div>
              <div className="flex items-center gap-2 text-xs font-medium text-gray-400 group-hover:text-white transition-colors">
                {copied ? (
                  <>
                    <Check className="h-4 w-4 text-green-400" />
                    <span className="text-green-400">Copied!</span>
                  </>
                ) : (
                  <>
                    <Copy className="h-4 w-4" />
                    <span>Copy</span>
                  </>
                )}
              </div>
            </button>
            <p className="text-center text-xs text-gray-400 mt-2">
              Click to copy the number
            </p>
          </div>

          <button 
            onClick={onClose}
            className="w-full py-3 bg-gray-100 text-gray-700 font-bold rounded-xl hover:bg-gray-200 transition-colors"
          >
            Close
          </button>

        </div>
      </div>
    </div>
  );
};

