-- 1. Enable UUID extension
create extension if not exists "uuid-ossp";

-- 2. Create Tables

-- PROFILES (Linked to Auth)
-- Added 'role' column
create table if not exists profiles (
  id uuid references auth.users on delete cascade not null primary key,
  email text,
  full_name text,
  role text default 'student' check (role in ('student', 'teacher', 'admin')),
  xp integer default 0,
  level integer default 1,
  credits integer default 0,
  subscription_tier text default 'free' check (subscription_tier in ('free', 'pro')),
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- PROFESSORS (Teachers)
-- Note: In a real app, a Professor entry might be linked to a Profile with role='teacher'
create table if not exists professors (
  id uuid default uuid_generate_v4() primary key,
  name text not null,
  avatar_url text,
  specialty text,
  rating numeric(3, 2) default 0.00,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- COURSES
create table if not exists courses (
  id uuid default uuid_generate_v4() primary key,
  title text not null,
  code text not null,
  description text,
  professor_id uuid references professors(id) on delete set null,
  image_url text,
  price_full integer not null,
  price_single integer not null,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- LECTURES
create table if not exists lectures (
  id uuid default uuid_generate_v4() primary key,
  course_id uuid references courses(id) on delete cascade not null,
  title text not null,
  start_time timestamp with time zone not null,
  duration_minutes integer not null,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- ACHIEVEMENTS
create table if not exists achievements (
  id uuid default uuid_generate_v4() primary key,
  title text not null,
  description text,
  icon_name text not null,
  xp_reward integer default 50,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- USER ACHIEVEMENTS
create table if not exists user_achievements (
  id uuid default uuid_generate_v4() primary key,
  user_id uuid references profiles(id) on delete cascade not null,
  achievement_id uuid references achievements(id) on delete cascade not null,
  unlocked_at timestamp with time zone default timezone('utc'::text, now()) not null,
  unique(user_id, achievement_id)
);

-- BOOKINGS
-- Added 'status' column
create table if not exists bookings (
  id uuid default uuid_generate_v4() primary key,
  user_id uuid references profiles(id) on delete cascade not null,
  course_id uuid references courses(id) on delete cascade not null,
  lecture_id uuid references lectures(id) on delete set null,
  booking_type text not null check (booking_type in ('full_course', 'single_lecture')),
  status text default 'pending' check (status in ('pending', 'approved', 'rejected')),
  amount_paid integer not null,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- 3. Row Level Security (RLS) Policies

-- Profiles
alter table profiles enable row level security;
create policy "Public profiles are viewable by everyone." on profiles for select using (true);
create policy "Users can update own profile." on profiles for update using (auth.uid() = id);

-- Professors (Public Read)
alter table professors enable row level security;
create policy "Professors are viewable by everyone." on professors for select using (true);

-- Courses (Public Read)
alter table courses enable row level security;
create policy "Courses are viewable by everyone." on courses for select using (true);

-- Lectures (Public Read)
alter table lectures enable row level security;
create policy "Lectures are viewable by everyone." on lectures for select using (true);

-- Achievements (Public Read)
alter table achievements enable row level security;
create policy "Achievements are viewable by everyone." on achievements for select using (true);

-- User Achievements (Private Read)
alter table user_achievements enable row level security;
create policy "Users can view own achievements." on user_achievements for select using (auth.uid() = user_id);

-- Bookings (Complex RLS for roles)
alter table bookings enable row level security;

-- Users can see their own bookings
create policy "Users can view own bookings." on bookings for select using (auth.uid() = user_id);

-- Admins can see all bookings (This requires a check on the auth.users metadata or a lookup on profiles, 
-- simplest way in pure SQL RLS without custom claims is strictly referencing the profiles table)
create policy "Admins can view all bookings" on bookings for select 
using (
  exists (select 1 from profiles where id = auth.uid() and role = 'admin')
);

-- Users can insert bookings (defaults to pending)
create policy "Users can insert bookings." on bookings for insert with check (auth.uid() = user_id);

-- Admins can update bookings (to approve them)
create policy "Admins can update bookings" on bookings for update 
using (
  exists (select 1 from profiles where id = auth.uid() and role = 'admin')
);

-- 4. Auth Triggers
-- Automatically creates a profile entry when a new user signs up via Supabase Auth
create or replace function public.handle_new_user()
returns trigger as $$
begin
  insert into public.profiles (id, full_name, email, role)
  values (new.id, new.raw_user_meta_data->>'full_name', new.email, 'student');
  return new;
end;
$$ language plpgsql security definer;

-- Drop trigger if exists to avoid conflicts on re-runs
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();

