import React, { createContext, useContext, useState, useEffect } from 'react';
import { User, UserRole } from '../types';
import { MOCK_USER, MOCK_ADMIN, MOCK_TEACHER } from '../constants';

interface AuthContextType {
  user: User | null;
  login: (email: string, role?: UserRole) => void;
  logout: () => void;
  isAuthenticated: boolean;
}

const AuthContext = createContext<AuthContextType>({
  user: null,
  login: () => {},
  logout: () => {},
  isAuthenticated: false,
});

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    // Check local storage on mount
    const storedUser = localStorage.getItem('finki_user');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
  }, []);

  const login = (email: string, role: UserRole = 'student') => {
    // Mock login logic
    let newUser: User;

    if (email.includes('admin')) {
        newUser = { ...MOCK_ADMIN, email };
    } else if (email.includes('prof') || role === 'teacher') {
        newUser = { ...MOCK_TEACHER, email };
    } else {
        newUser = { 
            ...MOCK_USER, 
            email: email,
            name: email.split('@')[0] || 'Student',
            role: 'student' 
        };
    }

    setUser(newUser);
    localStorage.setItem('finki_user', JSON.stringify(newUser));
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem('finki_user');
  };

  return (
    <AuthContext.Provider value={{ user, login, logout, isAuthenticated: !!user }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);

