                </p>
              </div>
            </div>
          </div>

        </div>
      </div>

      <BookingModal 
        course={course}
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        bookingType={bookingType}
        selectedLectureId={selectedLectureId}
