-- FINKI Tutors - Production Schema

-- 1. Enable UUID extension
create extension if not exists "uuid-ossp";

-- 2. ENUMS
create type user_role as enum ('student', 'teacher', 'admin');
create type booking_status as enum ('pending', 'approved', 'rejected');
create type booking_type_enum as enum ('single', 'full');

-- 3. PROFILES
-- Stores user data linked to Supabase Auth
create table if not exists profiles (
  id uuid references auth.users on delete cascade primary key,
  email text unique not null,
  full_name text,
  role user_role default 'student',
  xp integer default 0,
  level integer default 1,
  credits integer default 0,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- 4. SITE CONFIGURATION
-- Stores dynamic landing page data manageable by Admin
create table if not exists site_config (
  id integer primary key generated always as identity,
  key text unique not null,
  value jsonb not null,
  updated_at timestamp with time zone default timezone('utc'::text, now())
);

-- Seed initial site config
insert into site_config (key, value) values 
('landing_page', '{
  "heroTitle": "Master your subjects at",
  "heroSubtitle": "Book expert professors for specific lectures or full courses. Flexible pricing designed for students.",
  "statsStudents": "1,200+",
  "statsProfessors": "50+",
  "statsLectures": "3,500+",
  "statsPassRate": "98%"
}'::jsonb)
on conflict (key) do nothing;

-- 5. COURSES
create table if not exists courses (
  id uuid default uuid_generate_v4() primary key,
  title text not null,
  code text not null,
  description text,
  professor_name text, -- Simplified for launch, can be linked to a profiles id later if professors map 1:1
  professor_avatar text,
  image_url text,
  price_full integer not null default 6000,
  price_single integer not null default 750,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- 6. LECTURES
create table if not exists lectures (
  id uuid default uuid_generate_v4() primary key,
  course_id uuid references courses(id) on delete cascade,
  title text not null,
  start_time timestamp with time zone not null,
  duration_minutes integer default 90
);

-- 7. BOOKINGS
create table if not exists bookings (
  id uuid default uuid_generate_v4() primary key,
  user_id uuid references profiles(id) on delete cascade,
  user_email text, -- Cached for easier display
  course_id uuid references courses(id) on delete cascade,
  course_title text, -- Cached for easier display
  lecture_id uuid references lectures(id) on delete set null, -- Nullable if full course
  type booking_type_enum not null,
  status booking_status default 'pending',
  date timestamp with time zone not null,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- 8. ACHIEVEMENTS
create table if not exists achievements (
  id uuid default uuid_generate_v4() primary key,
  title text not null,
  description text,
  icon text not null,
  xp_reward integer default 100
);

create table if not exists user_achievements (
  id uuid default uuid_generate_v4() primary key,
  user_id uuid references profiles(id) on delete cascade,
  achievement_id uuid references achievements(id) on delete cascade,
  unlocked_at timestamp with time zone default timezone('utc'::text, now()),
  unique(user_id, achievement_id)
);

-- 9. RLS POLICIES (Row Level Security)

-- Enable RLS
alter table profiles enable row level security;
alter table bookings enable row level security;
alter table site_config enable row level security;

-- Profiles Policies
create policy "Public profiles are viewable by everyone" on profiles for select using (true);
create policy "Users can update own profile" on profiles for update using (auth.uid() = id);

-- Site Config Policies
create policy "Config viewable by everyone" on site_config for select using (true);
create policy "Admins can update config" on site_config for update using (
  exists (select 1 from profiles where id = auth.uid() and role = 'admin')
);

-- Bookings Policies
create policy "Users view own bookings" on bookings for select using (auth.uid() = user_id);
create policy "Teachers/Admins view all bookings" on bookings for select using (
  exists (select 1 from profiles where id = auth.uid() and role in ('admin', 'teacher'))
);
create policy "Users insert own bookings" on bookings for insert with check (auth.uid() = user_id);
create policy "Admins/Teachers update bookings" on bookings for update using (
  exists (select 1 from profiles where id = auth.uid() and role in ('admin', 'teacher'))
);

-- 10. TRIGGERS

-- Handle New User (Auto-create profile)
create or replace function public.handle_new_user()
returns trigger as $$
begin
  insert into public.profiles (id, email, full_name, role, xp, level, credits)
  values (
    new.id, 
    new.email, 
    new.raw_user_meta_data->>'full_name', 
    'student', -- Default role
    0, -- Reset XP
    1, -- Reset Level
    0  -- Reset Credits
  );
  return new;
end;
$$ language plpgsql security definer;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();

