import React, { createContext, useContext, useState, useEffect } from 'react';
import { User, UserRole } from '../types';
import { supabase, isSupabaseConfigured } from '../supabaseClient';
import { MOCK_USER, MOCK_ADMIN, MOCK_TEACHER } from '../constants';

interface AuthContextType {
  user: User | null;
  login: (email: string, password?: string) => Promise<void>;
  signup: (email: string, password: string, name: string) => Promise<void>;
  logout: () => void;
  isAuthenticated: boolean;
  loading: boolean;
}

const AuthContext = createContext<AuthContextType>({
  user: null,
  login: async () => {},
  signup: async () => {},
  logout: () => {},
  isAuthenticated: false,
  loading: false,
});

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const initAuth = async () => {
      if (isSupabaseConfigured() && supabase) {
        // Real Supabase Session Check
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
          const { data: profile } = await supabase
            .from('profiles')
            .select('*')
            .eq('id', session.user.id)
            .single();

          if (profile) {
            setUser({
              id: profile.id,
              name: profile.full_name,
              email: profile.email,
              role: profile.role,
              xp: profile.xp,
              level: profile.level,
              credits: profile.credits,
              subscriptionTier: 'free',
              bookedLectures: [],
              purchasedCourses: [],
              achievements: []
            });
          }
        }
      } else {
        // Mock Session Check
        const storedUser = localStorage.getItem('finki_user');
        if (storedUser) {
          setUser(JSON.parse(storedUser));
        }
      }
      setLoading(false);
    };

    initAuth();
  }, []);

  const login = async (email: string, password?: string) => {
    setLoading(true);

    if (isSupabaseConfigured() && supabase) {
      // Real Login
      const { error, data } = await supabase.auth.signInWithPassword({ email, password: password || 'password' });
      if (error) {
        setLoading(false);
        throw error;
      }

      if (data.user) {
        const { data: profile } = await supabase
          .from('profiles')
          .select('*')
          .eq('id', data.user.id)
          .single();

         if (profile) {
            setUser({
              id: profile.id,
              name: profile.full_name,
              email: profile.email,
              role: profile.role,
              xp: profile.xp,
              level: profile.level,
              credits: profile.credits,
              subscriptionTier: 'free',
              bookedLectures: [],
              purchasedCourses: [],
              achievements: []
            });
         }
      }
    } else {
      // Mock Login for Preview/Demo
      await new Promise(r => setTimeout(r, 800)); // Simulate net delay
      let newUser: User;

      if (email.includes('admin')) {
          newUser = { ...MOCK_ADMIN, email };
      } else if (email.includes('prof') || email.includes('teacher')) {
          newUser = { ...MOCK_TEACHER, email };
      } else {
          // Reset progress for students in mock mode to verify "0 XP" requirement
          newUser = { 
              ...MOCK_USER, 
              id: `u-${Date.now()}`,
              email: email,
              name: email.split('@')[0] || 'Student',
              role: 'student',
              xp: 0,
              level: 1,
              achievements: []
          };
      }

      setUser(newUser);
      localStorage.setItem('finki_user', JSON.stringify(newUser));
    }
    setLoading(false);
  };

  const signup = async (email: string, password: string, name: string) => {
    setLoading(true);
    if (isSupabaseConfigured() && supabase) {
      const { error, data } = await supabase.auth.signUp({
        email,
        password,
        options: {
          data: { full_name: name }
        }
      });
      if (error) throw error;
      // Triggers in Supabase will create the profile with 0 XP
    } else {
      // Mock Signup
      const newUser: User = {
        id: `u-${Date.now()}`,
        name,
        email,
        role: 'student',
        xp: 0,
        level: 1,
        credits: 0,
        subscriptionTier: 'free',
        bookedLectures: [],
        purchasedCourses: [],
        achievements: []
      };
      setUser(newUser);
      localStorage.setItem('finki_user', JSON.stringify(newUser));
    }
    setLoading(false);
  };

  const logout = async () => {
    if (isSupabaseConfigured() && supabase) {
      await supabase.auth.signOut();
    } else {
      localStorage.removeItem('finki_user');
    }
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, login, signup, logout, isAuthenticated: !!user, loading }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);

