interface DataContextType {
  courses: Course[];
  addCourse: (course: Course) => void;
  bookings: Booking[];
  addBooking: (booking: Booking) => Promise<void>;
  updateBookingStatus: (id: string, status: 'approved' | 'rejected') => Promise<void>;
  landingPageData: LandingPageData;
  updateLandingPage: (data: Partial<LandingPageData>) => Promise<void>;
  refreshData: () => Promise<void>;
}

const defaultLandingPage: LandingPageData = {
  heroTitle: "Master your subjects at",
  heroSubtitle: "Book expert professors for specific lectures or full courses. Flexible pricing designed for students.",
  statsStudents: "1,200+",
  statsProfessors: "50+",
  statsLectures: "3,500+",
  statsPassRate: "98%"
};

const DataContext = createContext<DataContextType>({
  courses: [],
  addCourse: () => {},
  bookings: [],
  addBooking: async () => {},
  updateBookingStatus: async () => {},
  landingPageData: defaultLandingPage,
  updateLandingPage: async () => {},
  refreshData: async () => {},
});

export const DataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { user } = useAuth();
  const [courses, setCourses] = useState<Course[]>(COURSES);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [landingPageData, setLandingPageData] = useState<LandingPageData>(defaultLandingPage);

  // Load Data
  const refreshData = async () => {
    if (isSupabaseConfigured() && supabase) {
      // 1. Fetch Config
      const { data: configData } = await supabase
        .from('site_config')
        .select('value')
        .eq('key', 'landing_page')
        .single();
      if (configData) setLandingPageData(configData.value);

      // 2. Fetch Bookings (Based on role)
      let query = supabase.from('bookings').select('*');
      if (user?.role === 'student') {
        query = query.eq('user_id', user.id);
      }
      // If teacher/admin, fetch all (or filter by teacher course later)
      const { data: bookingData } = await query;

      if (bookingData) {
        // Map DB fields to Type
        const mappedBookings: Booking[] = bookingData.map((b: any) => ({
            id: b.id,
            userId: b.user_id,
            courseId: b.course_id,
            courseTitle: b.course_title,
            date: b.date,
            type: b.type,
            status: b.status,
            userEmail: b.user_email
        }));
        setBookings(mappedBookings);
      }

      // 3. Fetch Courses (Optional if dynamic courses stored in DB)
      // For now using CONSTANTS + Memory for demo unless we implement full CRUD
    } else {
      // Mock Data Persistence
      const storedBookings = localStorage.getItem('finki_bookings');
      if (storedBookings) {
        const parsed = JSON.parse(storedBookings);
        // Filter if student
        if (user?.role === 'student') {
            setBookings(parsed.filter((b: Booking) => b.userEmail === user.email));
        } else {
            setBookings(parsed);
        }
      } else {
         setBookings(MOCK_BOOKINGS);
      }

      const storedConfig = localStorage.getItem('finki_config');
      if (storedConfig) setLandingPageData(JSON.parse(storedConfig));
    }
  };

  useEffect(() => {
    refreshData();
  }, [user]);

  const addCourse = (course: Course) => {
    setCourses(prev => [...prev, course]);
    // In real app, post to 'courses' table
  };

  const addBooking = async (booking: Booking) => {
    if (isSupabaseConfigured() && supabase) {
       await supabase.from('bookings').insert({
         user_id: user?.id,
         user_email: user?.email,
         course_id: booking.courseId, // Ensure mapped correctly
         course_title: booking.courseTitle,
         type: booking.type,
         status: 'pending',
         date: booking.date
       });
       refreshData();
    } else {
       const newBookings = [booking, ...bookings];
       setBookings(newBookings);
       // Save all bookings to local storage to simulate backend
       const allBookings = JSON.parse(localStorage.getItem('finki_bookings') || JSON.stringify(MOCK_BOOKINGS));
       localStorage.setItem('finki_bookings', JSON.stringify([booking, ...allBookings]));
    }
  };

  const updateBookingStatus = async (id: string, status: 'approved' | 'rejected') => {
    if (isSupabaseConfigured() && supabase) {
        await supabase.from('bookings').update({ status }).eq('id', id);
        refreshData();
    } else {
        const updated = bookings.map(b => b.id === id ? { ...b, status } : b);
        setBookings(updated);
        // Update local storage
        const allBookings = JSON.parse(localStorage.getItem('finki_bookings') || JSON.stringify(MOCK_BOOKINGS));
        const updatedAll = allBookings.map((b: Booking) => b.id === id ? { ...b, status } : b);
        localStorage.setItem('finki_bookings', JSON.stringify(updatedAll));
    }
  };

  const updateLandingPage = async (data: Partial<LandingPageData>) => {
    const newData = { ...landingPageData, ...data };
    setLandingPageData(newData);

    if (isSupabaseConfigured() && supabase) {
        await supabase.from('site_config').upsert({
            key: 'landing_page',
            value: newData
        }, { onConflict: 'key' });
    } else {
        localStorage.setItem('finki_config', JSON.stringify(newData));
    }
  };

  return (
    <DataContext.Provider value={{ 
      courses, 
      addCourse, 
      bookings, 
      addBooking, 
      updateBookingStatus,
      landingPageData, 
      updateLandingPage,
      refreshData
    }}>
      {children}
    </DataContext.Provider>
  );
};

