const AdminCourseManager: React.FC = () => {
    const { addCourse } = useData();
    const { notify } = useNotification();
    const [title, setTitle] = useState('');
    const [code, setCode] = useState('');
    const [price, setPrice] = useState(6000);

    const handleAdd = () => {
        if(!title || !code) return;
        addCourse({
            id: `c-${Date.now()}`,
            title,
            code,
            description: "New course added by admin.",
            professorId: 'p1', // Default to first prof for demo
            image: "https://picsum.photos/800/400?random=" + Math.random(),
            priceFull: Number(price),
            priceSingle: 750,
            lectures: []
        });
        notify('Course Added', `${title} is now live!`, 'success');
        setTitle('');
        setCode('');
    };

    return (
        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6">
            <h3 className="font-bold text-lg text-gray-900 mb-6 flex items-center gap-2">
                <Plus className="h-5 w-5 text-indigo-600" /> Add New Course
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
                <input placeholder="Course Title" className="p-2 border rounded-lg" value={title} onChange={e => setTitle(e.target.value)} />
                <input placeholder="Course Code (e.g. AI-101)" className="p-2 border rounded-lg" value={code} onChange={e => setCode(e.target.value)} />
                <input type="number" placeholder="Full Price" className="p-2 border rounded-lg" value={price} onChange={e => setPrice(Number(e.target.value))} />
            </div>
            <button onClick={handleAdd} className="w-full bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 font-bold">
                Add Course to Catalog
            </button>
        </div>
    )
}

