const AdminCourseManager: React.FC = () => {
    const { addCourse } = useData();
    const { notify } = useNotification();
    const [title, setTitle] = useState('');
    const [code, setCode] = useState('');
    const [description, setDescription] = useState('Online and group study available.');
    const [imageUrl, setImageUrl] = useState('');
    const [selectedProf, setSelectedProf] = useState(PROFESSORS[0].id);
    const [price, setPrice] = useState(6000);

    const handleAdd = () => {
        if(!title || !code || !selectedProf) {
            notify('Error', 'Please fill in all required fields.', 'info');
            return;
        }

        // Generate dummy lectures for calendar functionality
        const generatedLectures = Array.from({ length: 10 }).map((_, i) => ({
            id: `l-new-${Date.now()}-${i}`,
            title: `Lecture ${i + 1}: Introduction to ${title}`,
            date: new Date(Date.now() + (i + 1) * 86400000 * 2).toISOString(),
            duration: 90,
        }));

        addCourse({
            id: `c-${Date.now()}`,
            title,
            code,
            description: description,
            professorId: selectedProf,
            image: imageUrl || "https://picsum.photos/800/400?random=" + Math.random(),
            priceFull: Number(price),
            priceSingle: 750,
            lectures: generatedLectures
        });
        notify('Course Added', `${title} is now live and bookable!`, 'success');
        // Reset form
        setTitle('');
        setCode('');
        setDescription('Online and group study available.');
    };

    return (
        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6">
            <h3 className="font-bold text-lg text-gray-900 mb-6 flex items-center gap-2">
                <Plus className="h-5 w-5 text-indigo-600" /> Add New Course
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                <div className="col-span-2">
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Course Title</label>
                    <input placeholder="e.g. Advanced AI" className="w-full p-2 border rounded-lg" value={title} onChange={e => setTitle(e.target.value)} />
                </div>

                <div>
                     <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Course Code</label>
                     <input placeholder="e.g. AI-202" className="w-full p-2 border rounded-lg" value={code} onChange={e => setCode(e.target.value)} />
                </div>

                <div>
                     <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Full Price (MKD)</label>
                     <input type="number" className="w-full p-2 border rounded-lg" value={price} onChange={e => setPrice(Number(e.target.value))} />
                </div>

                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Assign Professor</label>
                    <select 
                        className="w-full p-2 border rounded-lg bg-white"
                        value={selectedProf}
                        onChange={e => setSelectedProf(e.target.value)}
                    >
                        {PROFESSORS.map(p => (
                            <option key={p.id} value={p.id}>{p.name} ({p.specialty})</option>
                        ))}
                    </select>
                </div>

                <div>
                     <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Image URL (Optional)</label>
                     <input placeholder="https://..." className="w-full p-2 border rounded-lg" value={imageUrl} onChange={e => setImageUrl(e.target.value)} />
                </div>

                <div className="col-span-2">
                     <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Description</label>
                     <textarea rows={3} className="w-full p-2 border rounded-lg" value={description} onChange={e => setDescription(e.target.value)} />
                </div>
            </div>
            <button onClick={handleAdd} className="w-full bg-green-600 text-white px-4 py-3 rounded-lg hover:bg-green-700 font-bold shadow-lg shadow-green-200">
                Add Course to Catalog
            </button>
        </div>
    )
}

