const AdminCourseManager: React.FC = () => {
    const { addCourse } = useData();
    const { notify } = useNotification();

    // Form State
    const [title, setTitle] = useState('');
    const [code, setCode] = useState('');
    const [description, setDescription] = useState('Online and group study available.');
    const [selectedProf, setSelectedProf] = useState(PROFESSORS[0].id);
    const [price, setPrice] = useState(6000);

    // Image Upload State
    const [imageFile, setImageFile] = useState<File | null>(null);
    const [imagePreview, setImagePreview] = useState<string>('');
    const [isDragging, setIsDragging] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    // Modules State
    const [lectures, setLectures] = useState<Array<{title: string, date: string, time: string}>>([]);
    const [newModTitle, setNewModTitle] = useState('');
    const [newModDate, setNewModDate] = useState('');
    const [newModTime, setNewModTime] = useState('');

    // Drag and Drop Handlers
    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(true);
    };

    const handleDragLeave = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        const file = e.dataTransfer.files[0];
        if (file && file.type.startsWith('image/')) {
            setImageFile(file);
            setImagePreview(URL.createObjectURL(file));
        }
    };

    const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            setImageFile(file);
            setImagePreview(URL.createObjectURL(file));
        }
    };

    const addModule = () => {
        if (!newModTitle || !newModDate || !newModTime) {
            notify('Error', 'Please fill all module fields', 'info');
            return;
        }
        setLectures([...lectures, { title: newModTitle, date: newModDate, time: newModTime }]);
        setNewModTitle('');
        setNewModDate('');
        setNewModTime('');
    };

    const removeLecture = (index: number) => {
        setLectures(lectures.filter((_, i) => i !== index));
    };

    const handleAddCourse = () => {
        if(!title || !code || !selectedProf) {
            notify('Error', 'Please fill in required fields', 'info');
            return;
        }
        if(lectures.length === 0) {
            notify('Error', 'Please add at least one module/lecture', 'info');
            return;
        }

        const finalLectures = lectures.map((l, i) => ({
            id: `l-new-${Date.now()}-${i}`,
            title: l.title,
            // Combine date and time
            date: new Date(`${l.date}T${l.time}`).toISOString(),
            duration: 90,
        }));

        addCourse({
            id: `c-${Date.now()}`,
            title,
            code,
            description,
            professorId: selectedProf,
            // Use preview URL for mock, in real app this is the storage URL
            image: imagePreview || "https://picsum.photos/800/400?random=" + Math.random(),
            priceFull: Number(price),
            priceSingle: 750,
            lectures: finalLectures
        });

        notify('Course Added', `${title} is now live with ${lectures.length} modules!`, 'success');

        // Reset form
        setTitle('');
        setCode('');
        setLectures([]);
        setImageFile(null);
        setImagePreview('');
        setNewModTitle('');
        setNewModDate('');
        setNewModTime('');
    };

    return (
        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6">
            <h3 className="font-bold text-lg text-gray-900 mb-6 flex items-center gap-2">
                <Plus className="h-5 w-5 text-indigo-600" /> Create New Course
            </h3>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                {/* Left Col: Course Info */}
                <div className="space-y-4">
                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Course Title</label>
                        <input placeholder="e.g. Advanced AI" className="w-full p-2 border rounded-lg" value={title} onChange={e => setTitle(e.target.value)} />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                             <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Code</label>
                             <input placeholder="AI-202" className="w-full p-2 border rounded-lg" value={code} onChange={e => setCode(e.target.value)} />
                        </div>
                        <div>
                             <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Price (MKD)</label>
                             <input type="number" className="w-full p-2 border rounded-lg" value={price} onChange={e => setPrice(Number(e.target.value))} />
                        </div>
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Assign Professor</label>
                        <select 
                            className="w-full p-2 border rounded-lg bg-white"
                            value={selectedProf}
                            onChange={e => setSelectedProf(e.target.value)}
                        >
                            {PROFESSORS.map(p => (
                                <option key={p.id} value={p.id}>{p.name}</option>
                            ))}
                        </select>
                    </div>
                     <div>
                         <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Description</label>
                         <textarea rows={3} className="w-full p-2 border rounded-lg" value={description} onChange={e => setDescription(e.target.value)} />
                    </div>
                </div>

                {/* Right Col: Image & Modules */}
                <div className="space-y-4">
                     <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Course Cover Image</label>
                        <div 
                            onDragOver={handleDragOver}
                            onDragLeave={handleDragLeave}
                            onDrop={handleDrop}
                            onClick={() => fileInputRef.current?.click()}
                            className={`border-2 border-dashed rounded-xl p-4 flex flex-col items-center justify-center cursor-pointer transition-colors h-32 ${
                                isDragging ? 'border-indigo-500 bg-indigo-50' : 'border-gray-300 hover:bg-gray-50'
                            } ${imagePreview ? 'p-0 overflow-hidden border-solid' : ''}`}
                        >
                            {imagePreview ? (
                                <div className="relative w-full h-full group">
                                    <img src={imagePreview} alt="Preview" className="w-full h-full object-cover" />
                                    <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                                        <p className="text-white font-bold text-sm">Change Image</p>
                                    </div>
                                </div>
                            ) : (
                                <>
                                    <UploadCloud className={`h-8 w-8 mb-2 ${isDragging ? 'text-indigo-500' : 'text-gray-400'}`} />
                                    <p className="text-xs text-gray-500 text-center">
                                        <span className="font-bold">Click to upload</span> or drag and drop<br/>
                                        SVG, PNG, JPG (max 800x400)
                                    </p>
                                </>
                            )}
                            <input 
                                type="file" 
                                ref={fileInputRef} 
                                className="hidden" 
                                accept="image/*" 
                                onChange={handleFileInput} 
                            />
                        </div>
                     </div>

                     <div className="bg-gray-50 rounded-xl p-4 border border-gray-100">
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-3 flex justify-between">
                            <span>Course Modules / Lectures</span>
                            <span className="text-indigo-600">{lectures.length} added</span>
                        </label>

                        <div className="space-y-2 mb-3 max-h-40 overflow-y-auto">
                            {lectures.map((l, i) => (
                                <div key={i} className="flex justify-between items-center bg-white p-2 rounded border border-gray-100 text-sm">
                                    <div className="truncate flex-1">
                                        <span className="font-bold block text-gray-900">{l.title}</span>
                                        <span className="text-xs text-gray-500">{l.date} at {l.time}</span>
                                    </div>
                                    <button onClick={() => removeLecture(i)} className="text-red-400 hover:text-red-600 p-1">
                                        <Trash2 className="h-4 w-4" />
                                    </button>
                                </div>
                            ))}
                            {lectures.length === 0 && <p className="text-xs text-gray-400 italic text-center py-2">No modules added yet.</p>}
                        </div>

                        <div className="grid grid-cols-1 gap-2">
                             <input 
                                placeholder="Module Title (e.g. Intro to Logic)" 
                                className="w-full p-2 border rounded text-sm"
                                value={newModTitle}
                                onChange={e => setNewModTitle(e.target.value)}
                             />
                             <div className="flex gap-2">
                                 <input 
                                    type="date" 
                                    className="flex-1 p-2 border rounded text-sm"
                                    value={newModDate}
                                    onChange={e => setNewModDate(e.target.value)}
                                 />
                                 <input 
                                    type="time" 
                                    className="w-24 p-2 border rounded text-sm"
                                    value={newModTime}
                                    onChange={e => setNewModTime(e.target.value)}
                                 />
                                 <button onClick={addModule} className="bg-indigo-600 text-white p-2 rounded hover:bg-indigo-700">
                                     <Plus className="h-4 w-4" />
                                 </button>
                             </div>
                        </div>
                     </div>
                </div>
            </div>

            <button onClick={handleAddCourse} className="w-full bg-green-600 text-white px-4 py-3 rounded-lg hover:bg-green-700 font-bold shadow-lg shadow-green-200">
                Create Course & Publish
            </button>
        </div>
    )
}

