    setLoading(true);
    if (isSupabaseConfigured() && supabase) {
      const { error, data } = await supabase.auth.signUp({
        email,
        password,
        options: {
          data: { full_name: name }
        }
      });
      if (error) throw error;
    } else {
      // Mock Signup
      const newUser: User = {
        id: `u-${Date.now()}`,
        name,
        email,
        role: 'student',
        xp: 0,
        level: 1,
        credits: 0,
        subscriptionTier: 'free',
        bookedLectures: [],
        purchasedCourses: [],
        achievements: []
      };
      setUser(newUser);
      localStorage.setItem('finki_user', JSON.stringify(newUser));
    }
    setLoading(false);
  };

  const updatePassword = async (password: string) => {
    setLoading(true);
    if (isSupabaseConfigured() && supabase) {
      const { error } = await supabase.auth.updateUser({ password });
      if (error) {
        setLoading(false);
        throw error;
      }
    } else {
      // Mock password update
      await new Promise(r => setTimeout(r, 1000));
