const SettingsTab: React.FC = () => {
    const { updatePassword } = useAuth();
    const { notify } = useNotification();
    const [newPass, setNewPass] = useState('');
    const [confirmPass, setConfirmPass] = useState('');
    const [loading, setLoading] = useState(false);

    const handleUpdate = async () => {
        if (!newPass || !confirmPass) {
            notify('Error', 'Please fill in all fields.', 'info');
            return;
        }
        if (newPass !== confirmPass) {
            notify('Error', 'Passwords do not match.', 'info');
            return;
        }
        if (newPass.length < 6) {
            notify('Error', 'Password must be at least 6 characters.', 'info');
            return;
        }

        setLoading(true);
        try {
            await updatePassword(newPass);
            notify('Success', 'Password updated successfully.', 'success');
            setNewPass('');
            setConfirmPass('');
        } catch (error: any) {
            notify('Error', error.message || 'Failed to update password', 'info');
        }
        setLoading(false);
    };

    return (
        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 max-w-2xl animate-fade-in-up">
            <h3 className="font-bold text-lg text-gray-900 mb-6 flex items-center gap-2">
                <Settings className="h-5 w-5 text-indigo-600" /> Account Settings
            </h3>

            <div className="space-y-6">
                <div className="bg-gray-50 p-6 rounded-xl border border-gray-100">
                    <h4 className="font-bold text-gray-800 mb-4 flex items-center gap-2">
                        <Lock className="h-4 w-4" /> Change Password
                    </h4>
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">New Password</label>
                            <input 
                                type="password" 
                                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                                placeholder="Min 6 characters"
                                value={newPass}
                                onChange={e => setNewPass(e.target.value)}
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Confirm New Password</label>
                            <input 
                                type="password" 
                                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                                placeholder="Re-enter password"
                                value={confirmPass}
                                onChange={e => setConfirmPass(e.target.value)}
                            />
                        </div>
                        <div className="pt-2">
                            <button 
                                onClick={handleUpdate}
                                disabled={loading}
                                className="bg-slate-900 text-white px-6 py-2.5 rounded-lg hover:bg-slate-800 font-bold disabled:opacity-50 transition-colors"
                            >
                                {loading ? 'Updating...' : 'Update Password'}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

