-- FINKI Tutors - Production Schema

-- 1. Enable UUID extension
create extension if not exists "uuid-ossp";

-- 2. ENUMS
drop type if exists user_role cascade;
drop type if exists booking_status cascade;
drop type if exists booking_type_enum cascade;

create type user_role as enum ('student', 'teacher', 'admin');
create type booking_status as enum ('pending', 'approved', 'rejected');
create type booking_type_enum as enum ('single', 'full');

-- 3. PROFILES
create table if not exists public.profiles (
  id uuid references auth.users on delete cascade primary key,
  email text unique not null,
  full_name text,
  role user_role default 'student',
  xp integer default 0,
  level integer default 1,
  credits integer default 0,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- 4. COURSES
create table if not exists public.courses (
  id uuid default uuid_generate_v4() primary key,
  title text not null,
  code text not null,
  description text,
  professor_id uuid references public.profiles(id),
  professor_name text,
  image text,
  price_full integer not null default 6000,
  price_single integer not null default 750,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- 5. LECTURES
create table if not exists public.lectures (
  id uuid default uuid_generate_v4() primary key,
  course_id uuid references public.courses(id) on delete cascade,
  title text not null,
  date timestamp with time zone not null,
  duration integer default 90,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- 6. BOOKINGS
create table if not exists public.bookings (
  id uuid default uuid_generate_v4() primary key,
  user_id uuid references public.profiles(id) on delete cascade,
  user_email text, 
  course_id uuid references public.courses(id) on delete cascade,
  course_title text,
  type booking_type_enum not null,
  status booking_status default 'pending',
  date timestamp with time zone not null,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- 7. SITE CONFIGURATION
create table if not exists public.site_config (
  id integer primary key generated always as identity,
  key text unique not null,
  value jsonb not null,
  updated_at timestamp with time zone default timezone('utc'::text, now())
);

-- Seed initial site config
insert into public.site_config (key, value) values 
('landing_page', '{
  "heroTitle": "Master your subjects at",
  "heroSubtitle": "Book expert professors for specific lectures or full courses. Flexible pricing designed for students.",
  "statsStudents": "1,200+",
  "statsProfessors": "50+",
  "statsLectures": "3,500+",
  "statsPassRate": "98%"
}'::jsonb)
on conflict (key) do nothing;

-- 8. ACHIEVEMENTS
create table if not exists public.achievements (
  id uuid default uuid_generate_v4() primary key,
  title text not null,
  description text,
  icon text not null,
  xp_reward integer default 100
);

-- 9. SECURITY (RLS)
alter table public.profiles enable row level security;
alter table public.courses enable row level security;
alter table public.lectures enable row level security;
alter table public.bookings enable row level security;
alter table public.site_config enable row level security;

-- POLICIES
create policy "Public profiles are viewable by everyone" on public.profiles for select using (true);
create policy "Users can update own profile" on public.profiles for update using (auth.uid() = id);

create policy "Courses viewable by everyone" on public.courses for select using (true);
create policy "Admins/Teachers insert courses" on public.courses for insert with check (exists (select 1 from public.profiles where id = auth.uid() and role in ('admin', 'teacher')));
create policy "Admins/Teachers update courses" on public.courses for update using (exists (select 1 from public.profiles where id = auth.uid() and role in ('admin', 'teacher')));

create policy "Lectures viewable by everyone" on public.lectures for select using (true);
create policy "Admins/Teachers manage lectures" on public.lectures for all using (exists (select 1 from public.profiles where id = auth.uid() and role in ('admin', 'teacher')));

create policy "Users view own bookings" on public.bookings for select using (auth.uid() = user_id);
create policy "Teachers/Admins view all bookings" on public.bookings for select using (exists (select 1 from public.profiles where id = auth.uid() and role in ('admin', 'teacher')));
create policy "Users insert own bookings" on public.bookings for insert with check (auth.uid() = user_id);
create policy "Admins/Teachers update bookings" on public.bookings for update using (exists (select 1 from public.profiles where id = auth.uid() and role in ('admin', 'teacher')));

create policy "Config viewable by everyone" on public.site_config for select using (true);
create policy "Admins update config" on public.site_config for update using (exists (select 1 from public.profiles where id = auth.uid() and role = 'admin'));

-- 10. NEW USER TRIGGER
create or replace function public.handle_new_user()
returns trigger as $$
begin
  insert into public.profiles (id, email, full_name, role)
  values (new.id, new.email, new.raw_user_meta_data->>'full_name', 'student');
  return new;
end;
$$ language plpgsql security definer;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();

