                  <button 
                    onClick={() => setBookingType('single')}
                    className={`flex-1 py-2 text-sm font-semibold rounded-lg transition-all ${bookingType === 'single' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                  >
