-- 1. Enable UUID extension
create extension if not exists "uuid-ossp";

-- 2. ENUMS (Resetting types to ensure clean state)
drop type if exists user_role cascade;
drop type if exists booking_status cascade;
drop type if exists booking_type_enum cascade;

create type user_role as enum ('student', 'teacher', 'admin');
create type booking_status as enum ('pending', 'approved', 'rejected');
create type booking_type_enum as enum ('single', 'full');

-- 3. PROFILES TABLE
-- This links extra data (Role, XP) to the standard Supabase Auth User
create table if not exists public.profiles (
  id uuid references auth.users on delete cascade primary key,
  email text unique not null,
  full_name text,
  role user_role default 'student',
  xp integer default 0,
  level integer default 1,
  credits integer default 0,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- 4. COURSES TABLE
create table if not exists public.courses (
  id uuid default uuid_generate_v4() primary key,
  title text not null,
  code text not null,
  description text,
  professor_id uuid references public.profiles(id),
  professor_name text,
  image text,
  price_full integer not null default 6000,
  price_single integer not null default 750,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- 5. LECTURES TABLE
create table if not exists public.lectures (
  id uuid default uuid_generate_v4() primary key,
  course_id uuid references public.courses(id) on delete cascade,
  title text not null,
  date timestamp with time zone not null,
  duration integer default 90,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- 6. BOOKINGS TABLE
create table if not exists public.bookings (
  id uuid default uuid_generate_v4() primary key,
  user_id uuid references public.profiles(id) on delete cascade,
  user_email text, 
  course_id uuid references public.courses(id) on delete cascade,
  course_title text,
  type booking_type_enum not null,
  status booking_status default 'pending',
  date timestamp with time zone not null,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- 7. SITE CONFIGURATION TABLE
create table if not exists public.site_config (
  id integer primary key generated always as identity,
  key text unique not null,
  value jsonb not null,
  updated_at timestamp with time zone default timezone('utc'::text, now())
);

