  exists (select 1 from public.profiles where id = auth.uid() and role in ('admin', 'teacher'))
);

-- CONFIG
create policy "Config viewable by everyone" on public.site_config for select using (true);
create policy "Admins update config" on public.site_config for update using (
  exists (select 1 from public.profiles where id = auth.uid() and role = 'admin')
);

-- 11. AUTOMATIC PROFILE CREATION TRIGGER (Crucial for Signup)
-- This function runs every time a user signs up via Supabase Auth
create or replace function public.handle_new_user()
returns trigger as $$
begin
  insert into public.profiles (id, email, full_name, role)
  values (
    new.id, 
    new.email, 
    new.raw_user_meta_data->>'full_name', 
    'student' -- Default role is student
  );
  return new;
end;
$$ language plpgsql security definer;

-- Bind the function to the auth table
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();

