        try {
          const { data: { session } } = await supabase.auth.getSession();
          if (session?.user) {
            const { data: profile } = await supabase
              .from('profiles')
              .select('*')
              .eq('id', session.user.id)
              .single();

            if (profile) {
              setUser({
                id: profile.id,
                name: profile.full_name,
                email: profile.email,
                role: profile.role,
                xp: profile.xp,
                level: profile.level,
                credits: profile.credits,
                subscriptionTier: 'free',
                bookedLectures: [],
                purchasedCourses: [],
                achievements: []
              });
            }
          }
        } catch (err) {
            console.error("Supabase auth check failed", err);
        }
      } 

      // 2. Fallback to Local Storage (Mock Mode) if no Supabase or Supabase failed/empty
      if (!user) {
        const storedUser = localStorage.getItem('finki_user');
        if (storedUser) {
          setUser(JSON.parse(storedUser));
        }
      }

      setLoading(false);
    };

    initAuth();
  }, []);

  const login = async (email: string, password?: string) => {
    setLoading(true);

    // Attempt Supabase Login first
    if (isSupabaseConfigured() && supabase) {
      try {
        const { error, data } = await supabase.auth.signInWithPassword({ email, password: password || 'password' });
        if (!error && data.user) {
          const { data: profile } = await supabase
            .from('profiles')
            .select('*')
            .eq('id', data.user.id)
            .single();

           if (profile) {
              const u: User = {
                id: profile.id,
                name: profile.full_name,
                email: profile.email,
                role: profile.role,
                xp: profile.xp,
                level: profile.level,
                credits: profile.credits,
                subscriptionTier: 'free',
                bookedLectures: [],
                purchasedCourses: [],
                achievements: []
              };
              setUser(u);
              setLoading(false);
              return; // Success with Supabase
           }
        } else {
            console.warn("Supabase login error:", error);
        }
      } catch (err) {
        console.warn("Supabase login failed, checking fallback options.", err);
      }
    }

    // --- CREDENTIAL CHECKS ---

    // Fallback Mock Login Logic 
    // We only allow this for specific hardcoded DEMO accounts (Admin/Teachers) 
    // to ensure you can still test these roles without creating them in DB immediately.

    const cleanEmail = email.toLowerCase().trim();
    const cleanPass = password?.trim();
    const isDemoAccount = ['gorazd.g.petkovski05@gmail.com', 'nikola.jankoski@gmail.com', 'dragan@gmail.com'].includes(cleanEmail);

    // If Supabase is configured and it's NOT a demo account, we do not allow mock login.
    if (isSupabaseConfigured() && !isDemoAccount) {
         setLoading(false);
         throw new Error('Invalid login credentials or account does not exist.');
    }

    await new Promise(r => setTimeout(r, 600)); // Simulate net delay
    let newUser: User | null = null;

    // Admin: gorazd.g.petkovski05@gmail.com / GorazdAdmin1!
    if (cleanEmail === 'gorazd.g.petkovski05@gmail.com' && cleanPass === 'GorazdAdmin1!') {
      newUser = { ...MOCK_ADMIN };
    } 
    // Teacher 1: nikola.jankoski@gmail.com / Nikola123
    else if (cleanEmail === 'nikola.jankoski@gmail.com' && cleanPass === 'Nikola123') {
      newUser = { ...MOCK_TEACHER_1 };
    }
    // Teacher 2: dragan@gmail.com / Dragan123
    else if (cleanEmail === 'dragan@gmail.com' && cleanPass === 'Dragan123') {
      newUser = { ...MOCK_TEACHER_2 };
    }
    // Generic Student Fallback (ONLY if Supabase is NOT configured)
    else if (!isSupabaseConfigured() && cleanPass && cleanPass.length >= 4) {
      newUser = { 
          ...MOCK_USER, 
          id: `u-${Date.now()}`,
          email: cleanEmail,
          name: cleanEmail.split('@')[0],
          role: 'student',
          xp: 0,
          level: 1,
          achievements: []
      };
    }

    if (newUser) {
      setUser(newUser);
      localStorage.setItem('finki_user', JSON.stringify(newUser));
    } else {
      setLoading(false);
      throw new Error('Invalid email or password');
    }

    setLoading(false);
  };

  const signup = async (email: string, password: string, name: string) => {
    setLoading(true);
    if (isSupabaseConfigured() && supabase) {
      const { error } = await supabase.auth.signUp({
        email,
        password,
        options: {
          data: { full_name: name }
        }
      });

      if (error) {
          setLoading(false);
          throw error;
      }

      // Success - return here so we don't create a mock user
      setLoading(false);
      return; 
    } 

    // Mock Signup (Only if Supabase not configured)
    const newUser: User = {
      id: `u-${Date.now()}`,
      name,
      email,
      role: 'student',
      xp: 0,
      level: 1,
      credits: 0,
      subscriptionTier: 'free',
      bookedLectures: [],
      purchasedCourses: [],
      achievements: []
    };
    setUser(newUser);
    localStorage.setItem('finki_user', JSON.stringify(newUser));
    setLoading(false);
  };

  const updatePassword = async (password: string) => {
    setLoading(true);
    try {
        if (isSupabaseConfigured() && supabase) {
            const { error } = await supabase.auth.updateUser({ password });
            if (error) throw error;
        } else {
            // Mock Update
            await new Promise(r => setTimeout(r, 1000));
        }
    } catch (e) {
        setLoading(false);
        throw e;
    }
    setLoading(false);
  };

  const logout = async () => {
    if (isSupabaseConfigured() && supabase) {
      await supabase.auth.signOut();
    } 
    localStorage.removeItem('finki_user');
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, login, signup, updatePassword, logout, isAuthenticated: !!user, loading }}>
      {children}
    </AuthContext.Provider>
  );
};

