on conflict (key) do nothing;

-- 9. ACHIEVEMENTS
create table public.achievements (
  id uuid default uuid_generate_v4() primary key,
  title text not null,
  description text,
  icon text not null,
  xp_reward integer default 100
);

-- 10. SECURITY (Row Level Security)
alter table public.profiles enable row level security;
alter table public.courses enable row level security;
alter table public.lectures enable row level security;
alter table public.bookings enable row level security;
alter table public.site_config enable row level security;

-- POLICIES

-- Profiles
create policy "Public profiles are viewable by everyone" on public.profiles for select using (true);
create policy "Users can update own profile" on public.profiles for update using (auth.uid() = id);

-- Courses
create policy "Courses viewable by everyone" on public.courses for select using (true);
create policy "Admins/Teachers insert courses" on public.courses for insert with check (
  exists (select 1 from public.profiles where id = auth.uid() and role in ('admin', 'teacher'))
);
create policy "Admins/Teachers update courses" on public.courses for update using (
  exists (select 1 from public.profiles where id = auth.uid() and role in ('admin', 'teacher'))
);

-- Lectures
create policy "Lectures viewable by everyone" on public.lectures for select using (true);
create policy "Admins/Teachers manage lectures" on public.lectures for all using (
  exists (select 1 from public.profiles where id = auth.uid() and role in ('admin', 'teacher'))
);

-- Bookings
create policy "Users view own bookings" on public.bookings for select using (auth.uid() = user_id);
create policy "Teachers/Admins view all bookings" on public.bookings for select using (
  exists (select 1 from public.profiles where id = auth.uid() and role in ('admin', 'teacher'))
);
create policy "Users insert own bookings" on public.bookings for insert with check (auth.uid() = user_id);
create policy "Admins/Teachers update bookings" on public.bookings for update using (
  exists (select 1 from public.profiles where id = auth.uid() and role in ('admin', 'teacher'))
);

-- Config
create policy "Config viewable by everyone" on public.site_config for select using (true);
create policy "Admins update config" on public.site_config for update using (
  exists (select 1 from public.profiles where id = auth.uid() and role = 'admin')
);

-- 11. AUTOMATIC PROFILE CREATION TRIGGER
-- Uses SECURITY DEFINER to bypass RLS restrictions during signup
create or replace function public.handle_new_user()
returns trigger as $$
begin
  insert into public.profiles (id, email, full_name, role)
  values (
    new.id, 
    new.email, 
    new.raw_user_meta_data->>'full_name', 
    'student'
  );
  return new;
end;
$$ language plpgsql security definer set search_path = public;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();

import React, { createContext, useContext, useState, useEffect } from 'react';
import { User, UserRole } from '../types';
import { supabase, isSupabaseConfigured } from '../supabaseClient';
import { MOCK_USER, MOCK_ADMIN, MOCK_TEACHER_1, MOCK_TEACHER_2 } from '../constants';

interface AuthContextType {
  user: User | null;
  login: (email: string, password?: string) => Promise<void>;
  signup: (email: string, password: string, name: string) => Promise<void>;
  resetPassword: (email: string) => Promise<void>;
  updatePassword: (password: string) => Promise<void>;
  logout: () => void;
  isAuthenticated: boolean;
  loading: boolean;
}

const AuthContext = createContext<AuthContextType>({
  user: null,
  login: async () => {},
  signup: async () => {},
  resetPassword: async () => {},
  updatePassword: async () => {},
  logout: () => {},
  isAuthenticated: false,
  loading: false,
});

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  // Helper to construct User object from Supabase Auth + Profile
  const getUserProfile = async (authId: string, authEmail?: string, authMeta?: any): Promise<User | null> => {
      try {
        const { data: profile, error } = await supabase
            .from('profiles')
            .select('*')
            .eq('id', authId)
            .single();

        // Even if profile fetch fails (row missing), we allow login if authId exists
        // This prevents "Account does not exist" errors for valid Auth users who lack a profile row
        return {
            id: authId,
            name: profile?.full_name || authMeta?.full_name || authEmail?.split('@')[0] || 'Student',
            email: profile?.email || authEmail || '',
            role: profile?.role || 'student',
            xp: profile?.xp || 0,
            level: profile?.level || 1,
            credits: profile?.credits || 0,
            subscriptionTier: 'free',
            bookedLectures: [],
            purchasedCourses: [],
            achievements: []
        };
      } catch (e) {
          console.error("Error fetching profile:", e);
          return null;
      }
  };

  useEffect(() => {
    const initAuth = async () => {
      if (isSupabaseConfigured() && supabase) {
        try {
          // 1. Check active session
          const { data: { session } } = await supabase.auth.getSession();
          if (session?.user) {
            const u = await getUserProfile(session.user.id, session.user.email, session.user.user_metadata);
            if (u) setUser(u);
          }

          // 2. Listen for auth changes (e.g., password recovery link clicked)
          supabase.auth.onAuthStateChange(async (event, session) => {
            if (event === 'SIGNED_IN' && session?.user) {
               const u = await getUserProfile(session.user.id, session.user.email, session.user.user_metadata);
               setUser(u);
            } else if (event === 'SIGNED_OUT') {
               setUser(null);
            } else if (event === 'PASSWORD_RECOVERY') {
               // User clicked reset link, they are now signed in with a recovery token
               // We should let them change password in dashboard
               if(session?.user) {
                   const u = await getUserProfile(session.user.id, session.user.email, session.user.user_metadata);
                   setUser(u);
               }
            }
          });

        } catch (err) {
            console.error("Supabase auth check failed", err);
        }
      } 

      // Fallback for Mock Mode
      if (!user) {
        const storedUser = localStorage.getItem('finki_user');
        if (storedUser) {
          setUser(JSON.parse(storedUser));
        }
      }

      setLoading(false);
    };

    initAuth();
  }, []);

  const login = async (email: string, password?: string) => {
    setLoading(true);
    const cleanEmail = email.trim().toLowerCase();

    // Attempt Supabase Login
    if (isSupabaseConfigured() && supabase) {
      try {
        const { error, data } = await supabase.auth.signInWithPassword({ 
            email: cleanEmail, 
            password: password || 'password' 
        });

        if (error) {
             console.warn("Supabase login error:", error.message);
             // Do NOT throw yet, check if it's a demo account fallback scenario
        } else if (data.user) {
           // SUCCESSFUL SUPABASE LOGIN
           const u = await getUserProfile(data.user.id, data.user.email, data.user.user_metadata);
           if (u) {
               setUser(u);
               setLoading(false);
               return; // Exit function successfully
           }
        }
      } catch (err) {
        console.warn("Supabase login exception:", err);
      }
    }

    // --- FALLBACK / DEMO ACCOUNTS ---

    const cleanPass = password?.trim();
    const isDemoAccount = ['gorazd.g.petkovski05@gmail.com', 'nikola.jankoski@gmail.com', 'dragan@gmail.com'].includes(cleanEmail);

    // If Supabase is configured and it's NOT a demo account, we do not allow mock login.
    // This prevents "fake" logins if the real DB login failed.
    if (isSupabaseConfigured() && !isDemoAccount) {
         setLoading(false);
         throw new Error('Invalid login credentials or account does not exist.');
    }

    await new Promise(r => setTimeout(r, 600)); // Simulate net delay
    let newUser: User | null = null;

    if (cleanEmail === 'gorazd.g.petkovski05@gmail.com' && cleanPass === 'GorazdAdmin1!') {
      newUser = { ...MOCK_ADMIN };
    } else if (cleanEmail === 'nikola.jankoski@gmail.com' && cleanPass === 'Nikola123') {
      newUser = { ...MOCK_TEACHER_1 };
    } else if (cleanEmail === 'dragan@gmail.com' && cleanPass === 'Dragan123') {
      newUser = { ...MOCK_TEACHER_2 };
    } else if (!isSupabaseConfigured() && cleanPass && cleanPass.length >= 4) {
      newUser = { 
          ...MOCK_USER, 
          id: `u-${Date.now()}`,
          email: cleanEmail,
          name: cleanEmail.split('@')[0],
          role: 'student',
          xp: 0,
          level: 1,
          achievements: []
      };
    }

    if (newUser) {
      setUser(newUser);
      localStorage.setItem('finki_user', JSON.stringify(newUser));
    } else {
      setLoading(false);
      throw new Error('Invalid email or password');
    }

    setLoading(false);
  };

  const signup = async (email: string, password: string, name: string) => {
    setLoading(true);
    const cleanEmail = email.trim();
    const cleanName = name.trim();

    if (isSupabaseConfigured() && supabase) {
      // This sends the password to Supabase Auth which hashes and saves it securely.
      const { error } = await supabase.auth.signUp({
        email: cleanEmail,
        password,
        options: {
          data: { full_name: cleanName }
        }
      });

      if (error) {
          setLoading(false);
          throw error;
      }

      setLoading(false);
      return; 
    } 

    // Mock Signup
    const newUser: User = {
      id: `u-${Date.now()}`,
      name: cleanName,
      email: cleanEmail,
      role: 'student',
      xp: 0,
      level: 1,
      credits: 0,
      subscriptionTier: 'free',
      bookedLectures: [],
      purchasedCourses: [],
      achievements: []
    };
    setUser(newUser);
    localStorage.setItem('finki_user', JSON.stringify(newUser));
    setLoading(false);
  };

  const resetPassword = async (email: string) => {
    setLoading(true);
    const cleanEmail = email.trim();

    if (isSupabaseConfigured() && supabase) {
      // This sends a magic link to the user's email
      const { error } = await supabase.auth.resetPasswordForEmail(cleanEmail, {
        redirectTo: window.location.origin + '/dashboard', 
      });
      if (error) {
        setLoading(false);
        throw error;
      }
    } else {
      await new Promise(r => setTimeout(r, 1000));
    }
    setLoading(false);
  };

  const updatePassword = async (password: string) => {
    setLoading(true);
    try {
        if (isSupabaseConfigured() && supabase) {
            const { error } = await supabase.auth.updateUser({ password });
            if (error) throw error;
        } else {
            await new Promise(r => setTimeout(r, 1000));
        }
    } catch (e) {
        setLoading(false);
        throw e;
    }
    setLoading(false);
  };

  const logout = async () => {
    if (isSupabaseConfigured() && supabase) {
      await supabase.auth.signOut();
    } 
    localStorage.removeItem('finki_user');
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, login, signup, resetPassword, updatePassword, logout, isAuthenticated: !!user, loading }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);

