import React, { createContext, useContext, useState, useEffect } from 'react';
import { Course, LandingPageData, Booking, User, UserRole, Lecture } from '../types';
import { COURSES, MOCK_BOOKINGS, MOCK_USER } from '../constants';
import { supabase, isSupabaseConfigured } from '../supabaseClient';
import { useAuth } from './AuthContext';

interface DataContextType {
  courses: Course[];
  addCourse: (course: Course) => Promise<void>;
  bookings: Booking[];
  addBooking: (booking: Booking) => Promise<void>;
  updateBookingStatus: (id: string, status: 'approved' | 'rejected') => Promise<void>;
  landingPageData: LandingPageData;
  updateLandingPage: (data: Partial<LandingPageData>) => Promise<void>;
  users: User[];
  updateUserRole: (userId: string, role: UserRole) => Promise<void>;
  refreshData: () => Promise<void>;
}

const defaultLandingPage: LandingPageData = {
  heroTitle: "Master your subjects at",
  heroSubtitle: "Book expert professors for specific lectures or full courses. Flexible pricing designed for students.",
  statsStudents: "1,200+",
  statsProfessors: "50+",
  statsLectures: "3,500+",
  statsPassRate: "98%"
};

const DataContext = createContext<DataContextType>({
  courses: [],
  addCourse: async () => {},
  bookings: [],
  addBooking: async () => {},
  updateBookingStatus: async () => {},
  landingPageData: defaultLandingPage,
  updateLandingPage: async () => {},
  users: [],
  updateUserRole: async () => {},
  refreshData: async () => {},
});

export const DataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { user } = useAuth();
  const [courses, setCourses] = useState<Course[]>(COURSES);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [landingPageData, setLandingPageData] = useState<LandingPageData>(defaultLandingPage);

  // Load Data
  const refreshData = async () => {
    if (isSupabaseConfigured() && supabase) {
      try {
        // 1. Fetch Config
        const { data: configData } = await supabase
          .from('site_config')
          .select('value')
          .eq('key', 'landing_page')
          .single();
        if (configData) setLandingPageData(configData.value);

        // 2. Fetch Courses (Dynamic from DB)
        const { data: coursesData, error: coursesError } = await supabase
          .from('courses')
          .select('*, lectures(*)');

        if (!coursesError && coursesData && coursesData.length > 0) {
            const mappedCourses: Course[] = coursesData.map((c: any) => ({
                id: c.id,
                title: c.title,
                code: c.code,
                description: c.description,
                professorId: c.professor_id || 'p1', // Fallback for UI if null
                professorName: c.professor_name,
                image: c.image,
                priceFull: c.price_full,
                priceSingle: c.price_single,
                lectures: c.lectures ? c.lectures.map((l: any) => ({
                    id: l.id,
                    title: l.title,
                    date: l.date,
                    duration: l.duration
                })) : []
            }));
            setCourses(mappedCourses);
        } else {
            // Fallback to constants if DB empty
            // setCourses(COURSES);
        }

        // 3. Fetch Bookings
        let query = supabase.from('bookings').select('*').order('created_at', { ascending: false });
        // RLS handles visibility, so we just fetch.
        const { data: bookingData } = await query;

        if (bookingData) {
          const mappedBookings: Booking[] = bookingData.map((b: any) => ({
              id: b.id,
              userId: b.user_id,
              userEmail: b.user_email,
              courseId: b.course_id,
              courseTitle: b.course_title,
              type: b.type,
              status: b.status,
              date: b.date,
          }));
          setBookings(mappedBookings);
        }

        // 4. Fetch Users (Admin Only)
        if (user?.role === 'admin') {
            const { data: userData } = await supabase
              .from('profiles')
              .select('*')
              .order('created_at', { ascending: false });

            if (userData) {
                const mappedUsers: User[] = userData.map((u: any) => ({
                    id: u.id,
                    name: u.full_name || 'Student',
                    email: u.email,
                    role: u.role,
                    xp: u.xp,
                    level: u.level,
                    credits: u.credits,
                    subscriptionTier: 'free',
                    bookedLectures: [],
                    purchasedCourses: [],
                    achievements: []
                }));
                setUsers(mappedUsers);
            }
        }
      } catch (err) {
        console.error("Error refreshing data:", err);
      }
    } else {
      // Mock Data Persistence
      const storedBookings = localStorage.getItem('finki_bookings');
      if (storedBookings) {
        const parsed = JSON.parse(storedBookings);
        if (user?.role === 'student') {
            setBookings(parsed.filter((b: Booking) => b.userEmail === user.email));
        } else {
            setBookings(parsed);
        }
      } else {
         setBookings(MOCK_BOOKINGS);
      }

      if (user?.role === 'admin') setUsers([MOCK_USER]); 

      const storedConfig = localStorage.getItem('finki_config');
      if (storedConfig) setLandingPageData(JSON.parse(storedConfig));
    }
  };

  useEffect(() => {
    refreshData();
  }, [user]);

  const addCourse = async (course: Course) => {
    if (isSupabaseConfigured() && supabase) {
        // Prepare lectures for insertion
        const { data: courseData, error: courseError } = await supabase.from('courses').insert({
            title: course.title,
            code: course.code,
            description: course.description,
            professor_id: course.professorId, // Ensure this ID matches a profile if strict FK is on
            image: course.image,
            price_full: course.priceFull,
            price_single: course.priceSingle
        }).select().single();

        if (courseError) throw courseError;

        if (courseData && course.lectures.length > 0) {
            const lectureInserts = course.lectures.map(l => ({
                course_id: courseData.id,
                title: l.title,
                date: l.date,
                duration: l.duration
            }));
            const { error: lecError } = await supabase.from('lectures').insert(lectureInserts);
            if (lecError) console.error("Error inserting lectures:", lecError);
        }
        await refreshData();
    } else {
        setCourses(prev => [...prev, course]);
    }
  };

  const addBooking = async (booking: Booking) => {
    if (isSupabaseConfigured() && supabase) {
       // Note: course_id must be a valid UUID existing in courses table
       const { error } = await supabase.from('bookings').insert({
         user_id: user?.id,
         user_email: user?.email,
         course_id: booking.courseId, 
         course_title: booking.courseTitle,
         type: booking.type,
         status: 'pending',
         date: booking.date
       });

       if (error) {
           console.error("Booking Error:", error);
           throw error; // Throw to stop loading spinner
       }
       await refreshData();
    } else {
       const newBookings = [booking, ...bookings];
       setBookings(newBookings);
       const allBookings = JSON.parse(localStorage.getItem('finki_bookings') || JSON.stringify(MOCK_BOOKINGS));
       localStorage.setItem('finki_bookings', JSON.stringify([booking, ...allBookings]));
       await new Promise(r => setTimeout(r, 500)); // Sim delay
    }
  };

  const updateBookingStatus = async (id: string, status: 'approved' | 'rejected') => {
    if (isSupabaseConfigured() && supabase) {
        const { error } = await supabase.from('bookings').update({ status }).eq('id', id);
        if (error) throw error;
        await refreshData();
    } else {
        const updated = bookings.map(b => b.id === id ? { ...b, status } : b);
        setBookings(updated);
        const allBookings = JSON.parse(localStorage.getItem('finki_bookings') || JSON.stringify(MOCK_BOOKINGS));
        const updatedAll = allBookings.map((b: Booking) => b.id === id ? { ...b, status } : b);
        localStorage.setItem('finki_bookings', JSON.stringify(updatedAll));
    }
  };

  const updateLandingPage = async (data: Partial<LandingPageData>) => {
    const newData = { ...landingPageData, ...data };
    setLandingPageData(newData);

    if (isSupabaseConfigured() && supabase) {
        await supabase.from('site_config').upsert({
            key: 'landing_page',
            value: newData
        }, { onConflict: 'key' });
    } else {
        localStorage.setItem('finki_config', JSON.stringify(newData));
    }
  };

  const updateUserRole = async (userId: string, role: UserRole) => {
      if (isSupabaseConfigured() && supabase) {
          const { error } = await supabase.from('profiles').update({ role }).eq('id', userId);
          if (error) throw error;
          await refreshData();
      } else {
          setUsers(users.map(u => u.id === userId ? { ...u, role } : u));
      }
  };

  return (
    <DataContext.Provider value={{ 
      courses, 
      addCourse, 
      bookings, 
      addBooking, 
      updateBookingStatus,
      landingPageData, 
      updateLandingPage,
      users, 
      updateUserRole,
      refreshData
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => useContext(DataContext);

