                                    ))
                                )}
                                </div>
                            </div>
                        )}
                   </>
                )}

                {/* CALENDAR TAB */}
                {activeTab === 'calendar' && (
                    <SquareCalendar bookings={myBookings} />
                )}
            </div>

            <div className="space-y-8">
                <AnalyticsCard role={user.role} />
                <AiTutor />
            </div>
        </div>
      </div>
    </div>
  );
};

