import React, { createContext, useContext, useState, useEffect } from 'react';
import { Course, LandingPageData, Booking, User, UserRole, Lecture } from '../types';
import { COURSES, MOCK_BOOKINGS, MOCK_USER } from '../constants';
import { supabase, isSupabaseConfigured } from '../supabaseClient';
import { useAuth } from './AuthContext';

interface DataContextType {
  courses: Course[];
  addCourse: (course: Course) => Promise<void>;
  bookings: Booking[];
  addBooking: (booking: Booking) => Promise<void>;
  updateBookingStatus: (id: string, status: 'approved' | 'rejected') => Promise<void>;
  landingPageData: LandingPageData;
  updateLandingPage: (data: Partial<LandingPageData>) => Promise<void>;
  users: User[];
  updateUserRole: (userId: string, role: UserRole) => Promise<void>;
  refreshData: () => Promise<void>;
}

const defaultLandingPage: LandingPageData = {
  heroTitle: "Master your subjects at",
  heroSubtitle: "Book expert professors for specific lectures or full courses. Flexible pricing designed for students.",
  statsStudents: "1,200+",
  statsProfessors: "50+",
  statsLectures: "3,500+",
  statsPassRate: "98%"
};

const DataContext = createContext<DataContextType>({
  courses: [],
  addCourse: async () => {},
  bookings: [],
  addBooking: async () => {},
  updateBookingStatus: async () => {},
  landingPageData: defaultLandingPage,
  updateLandingPage: async () => {},
  users: [],
  updateUserRole: async () => {},
  refreshData: async () => {},
});

export const DataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { user } = useAuth();
  const [courses, setCourses] = useState<Course[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [landingPageData, setLandingPageData] = useState<LandingPageData>(defaultLandingPage);

  // Load Data
  const refreshData = async () => {
    if (isSupabaseConfigured() && supabase) {
      try {
        // 1. Fetch Config
        const { data: configData } = await supabase
          .from('site_config')
          .select('value')
          .eq('key', 'landing_page')
          .single();
        if (configData) setLandingPageData(configData.value);

        // 2. Fetch Courses (Dynamic from DB)
        const { data: coursesData, error: coursesError } = await supabase
          .from('courses')
          .select('*, lectures(*)');

        if (!coursesError && coursesData && coursesData.length > 0) {
            const mappedCourses: Course[] = coursesData.map((c: any) => ({
                id: c.id,
                title: c.title,
                code: c.code,
                description: c.description,
                professorId: c.professor_id || 'p1', 
                professorName: c.professor_name,
                image: c.image,
                priceFull: c.price_full,
                priceSingle: c.price_single,
                lectures: c.lectures ? c.lectures.map((l: any) => ({
                    id: l.id,
                    title: l.title,
                    date: l.date,
                    duration: l.duration
                })) : []
            }));
            setCourses(mappedCourses);
        } else {
            // If DB is empty, we do NOT load mock courses because IDs will clash.
            // The seed script should handle initial data.
            setCourses([]);
        }

        // 3. Fetch Bookings
        let query = supabase.from('bookings').select('*').order('created_at', { ascending: false });
        const { data: bookingData, error: bookingError } = await query;

        if (bookingData) {
          const mappedBookings: Booking[] = bookingData.map((b: any) => ({
              id: b.id,
              userId: b.user_id,
              userEmail: b.user_email,
              courseId: b.course_id,
              courseTitle: b.course_title,
              type: b.type,
              status: b.status,
              date: b.date,
          }));
          setBookings(mappedBookings);
        }

        // 4. Fetch Users (Admin Only)
        if (user?.role === 'admin') {
            const { data: userData } = await supabase
              .from('profiles')
              .select('*')
              .order('created_at', { ascending: false });

            if (userData) {
                const mappedUsers: User[] = userData.map((u: any) => ({
                    id: u.id,
                    name: u.full_name || 'Student',
                    email: u.email,
                    role: u.role,
                    xp: u.xp,
                    level: u.level,
                    credits: u.credits,
                    subscriptionTier: 'free',
                    bookedLectures: [],
                    purchasedCourses: [],
                    achievements: []
                }));
                setUsers(mappedUsers);
            }
        }
      } catch (err) {
        console.error("Error refreshing data:", err);
      }
    } else {
      // Mock Data Persistence
      setCourses(COURSES);
      const storedBookings = localStorage.getItem('finki_bookings');
      if (storedBookings) {
        const parsed = JSON.parse(storedBookings);
        if (user?.role === 'student') {
            setBookings(parsed.filter((b: Booking) => b.userEmail === user.email));
        } else {
            setBookings(parsed);
        }
      } else {
         setBookings(MOCK_BOOKINGS);
      }

      if (user?.role === 'admin') setUsers([MOCK_USER]); 

      const storedConfig = localStorage.getItem('finki_config');
      if (storedConfig) setLandingPageData(JSON.parse(storedConfig));
    }
  };

  useEffect(() => {
    refreshData();
  }, [user]);

  const addCourse = async (course: Course) => {
    if (isSupabaseConfigured() && supabase) {

        // FIX: Blob URLs crash the DB. Revert to placeholder if real URL not present.
        let safeImage = course.image;
        if (safeImage.startsWith('blob:')) {
            // Using a random placeholder because we don't have Storage setup in this context
            safeImage = `https://source.unsplash.com/random/800x600?study,${course.code}`;
        }

        const { data: courseData, error: courseError } = await supabase.from('courses').insert({
            title: course.title,
            code: course.code,
            description: course.description,
            professor_id: course.professorId, 
            image: safeImage,
            price_full: course.priceFull,
            price_single: course.priceSingle
        }).select().single();

        if (courseError) {
            console.error("Supabase Add Course Error:", courseError);
            throw new Error(courseError.message);
        }

        if (courseData && course.lectures.length > 0) {
            const lectureInserts = course.lectures.map(l => ({
                course_id: courseData.id,
                title: l.title,
                date: l.date,
                duration: l.duration
            }));
            const { error: lecError } = await supabase.from('lectures').insert(lectureInserts);
            if (lecError) console.error("Error inserting lectures:", lecError);
        }
        await refreshData();
    } else {
        setCourses(prev => [...prev, course]);
    }
  };

  const addBooking = async (booking: Booking) => {
    if (isSupabaseConfigured() && supabase) {
       // Note: course_id must be a valid UUID existing in courses table
       const { error } = await supabase.from('bookings').insert({
         user_id: user?.id,
         user_email: user?.email,
         course_id: booking.courseId, 
         course_title: booking.courseTitle,
         type: booking.type,
         status: 'pending',
         date: booking.date
       });

       if (error) {
           console.error("Booking Error:", error);
           throw new Error(`Booking failed: ${error.message}`); 
       }
       await refreshData();
    } else {
       const newBookings = [booking, ...bookings];
       setBookings(newBookings);
       const allBookings = JSON.parse(localStorage.getItem('finki_bookings') || JSON.stringify(MOCK_BOOKINGS));
       localStorage.setItem('finki_bookings', JSON.stringify([booking, ...allBookings]));
       await new Promise(r => setTimeout(r, 500)); // Sim delay
    }
  };

  const updateBookingStatus = async (id: string, status: 'approved' | 'rejected') => {
    if (isSupabaseConfigured() && supabase) {
        const { error } = await supabase.from('bookings').update({ status }).eq('id', id);
        if (error) throw error;
        await refreshData();
    } else {
        const updated = bookings.map(b => b.id === id ? { ...b, status } : b);
        setBookings(updated);
        const allBookings = JSON.parse(localStorage.getItem('finki_bookings') || JSON.stringify(MOCK_BOOKINGS));
        const updatedAll = allBookings.map((b: Booking) => b.id === id ? { ...b, status } : b);
        localStorage.setItem('finki_bookings', JSON.stringify(updatedAll));
    }
  };

  const updateLandingPage = async (data: Partial<LandingPageData>) => {
    const newData = { ...landingPageData, ...data };
    setLandingPageData(newData);

    if (isSupabaseConfigured() && supabase) {
        await supabase.from('site_config').upsert({
            key: 'landing_page',
            value: newData
        }, { onConflict: 'key' });
    } else {
        localStorage.setItem('finki_config', JSON.stringify(newData));
    }
  };

  const updateUserRole = async (userId: string, role: UserRole) => {
      if (isSupabaseConfigured() && supabase) {
          const { error } = await supabase.from('profiles').update({ role }).eq('id', userId);
          if (error) throw error;
          await refreshData();
      } else {
          setUsers(users.map(u => u.id === userId ? { ...u, role } : u));
      }
  };

  return (
    <DataContext.Provider value={{ 
      courses, 
      addCourse, 
      bookings, 
      addBooking, 
      updateBookingStatus,
      landingPageData, 
      updateLandingPage,
      users, 
      updateUserRole,
      refreshData
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => useContext(DataContext);

import React, { useState } from 'react';
import { Course, BookingType } from '../types';
import { X, Check, Copy, Phone, Wallet, Info, LogIn, UserPlus, Loader, AlertTriangle } from 'lucide-react';
import { Link } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useData } from '../contexts/DataContext';
import { useNotification } from '../contexts/NotificationContext';
import { useLanguage } from '../contexts/LanguageContext';

interface BookingModalProps {
  course: Course | null;
  isOpen: boolean;
  onClose: () => void;
  bookingType: BookingType;
  selectedLectureId?: string;
  price: number;
}

export const BookingModal: React.FC<BookingModalProps> = ({ 
  course, 
  isOpen, 
  onClose, 
  bookingType, 
  selectedLectureId, 
  price 
}) => {
  const { isAuthenticated, user } = useAuth();
  const { addBooking } = useData();
  const { notify } = useNotification();
  const { t } = useLanguage();
  const [copied, setCopied] = useState(false);
  const [requestSent, setRequestSent] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  if (!isOpen || !course) return null;

  if (user?.role === 'teacher') return null;

  const phoneNumber = "+389 71 555 999";

  const handleCopy = () => {
    navigator.clipboard.writeText(phoneNumber);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleConfirmBooking = async () => {
    if (!user) return;
    setError('');

    // 1. Validate Selection
    if (bookingType === 'single' && !selectedLectureId) {
        setError("Please select a specific lecture date.");
        return;
    }

    setLoading(true);

    try {
        const selectedLecture = course.lectures.find(l => l.id === selectedLectureId);

        const dateToBook = bookingType === 'single' && selectedLecture 
            ? selectedLecture.date 
            : course.lectures[0]?.date || new Date().toISOString();

        if (!dateToBook) {
            throw new Error("Invalid date selected. Please try again.");
        }

        await addBooking({
            id: `b-${Date.now()}`, // Temporary ID, DB assigns real one
            userId: user.id,
            userEmail: user.email,
            courseId: course.id,
            courseTitle: course.title,
            type: bookingType,
            status: 'pending',
            date: dateToBook
        });

        notify('Success', t('requestSent'), 'success');
        setRequestSent(true); // This switches the UI to success state
    } catch (e: any) {
        console.error("Booking Error Catch:", e);
        setError(e.message || 'Failed to send booking request.');
        notify('Error', 'Failed to send booking request.', 'info');
    } finally {
        setLoading(false);
    }
  };

  const selectedLecture = course.lectures.find(l => l.id === selectedLectureId);

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto">
      <div className="flex items-center justify-center min-h-screen px-4 text-center">
        <div className="fixed inset-0 bg-gray-900/60 backdrop-blur-sm transition-opacity" onClick={onClose}></div>

        <div className="inline-block w-full max-w-md p-6 my-8 overflow-hidden text-left align-middle transition-all transform bg-white shadow-2xl rounded-2xl border border-gray-100 relative">

          <div className="flex justify-between items-start mb-6">
            <div>
              <h3 className="text-xl font-bold text-gray-900">
                 {isAuthenticated ? t('completeBooking') : t('contactLogin')}
              </h3>
              <p className="text-sm text-gray-500 mt-1">
                 {isAuthenticated ? t('confirmSpot') : t('loginRequired')}
              </p>
            </div>
            <button onClick={onClose} className="p-1 rounded-full hover:bg-gray-100 transition-colors">
              <X className="h-6 w-6 text-gray-400" />
            </button>
          </div>

          {!requestSent ? (
            <>
              {error && (
                  <div className="mb-4 p-3 bg-red-50 text-red-700 text-sm rounded-lg flex items-center gap-2 border border-red-100">
                      <AlertTriangle className="h-4 w-4" /> {error}
                  </div>
              )}

              <div className="bg-gray-50 rounded-xl p-4 mb-6 border border-gray-100">
                <h4 className="font-semibold text-gray-900 mb-2">{course.title}</h4>
                <div className="flex items-center gap-2 text-sm text-gray-600 mb-1">
                  <span className={`px-2 py-0.5 rounded text-xs font-bold uppercase ${bookingType === 'full' ? 'bg-indigo-100 text-indigo-700' : 'bg-blue-100 text-blue-700'}`}>
                    {bookingType === 'full' ? t('fullCourseBundle') : t('singleLecture')}
                  </span>
                  {bookingType === 'single' && selectedLecture && (
                    <span className="truncate max-w-[200px]">- {selectedLecture.title}</span>
                  )}
                </div>
                <div className="mt-3 pt-3 border-t border-gray-200 flex justify-between items-center">
                  <span className="text-gray-600 font-medium">{t('totalAmount')}</span>
                  <span className="text-2xl font-bold text-gray-900">{price} MKD</span>
                </div>
              </div>

              <div className="mb-6">
                <div className="flex items-center gap-2 mb-3">
                  <div className="bg-green-100 p-2 rounded-lg">
                    <Wallet className="h-5 w-5 text-green-600" />
                  </div>
                  <h4 className="font-bold text-gray-900">{t('cashOnly')}</h4>
                </div>
                <p className="text-sm text-gray-600 leading-relaxed bg-yellow-50 p-3 rounded-lg border border-yellow-100 text-yellow-800">
                  <Info className="h-4 w-4 inline mr-1 mb-0.5" />
                  {t('paymentInfo')}
                </p>
              </div>

              <div className="mb-8">
                <button 
                  onClick={handleCopy}
                  className="w-full flex items-center justify-between p-4 bg-slate-900 hover:bg-slate-800 text-white rounded-xl transition-all group active:scale-[0.98]"
                >
                  <div className="flex items-center gap-3">
                    <Phone className="h-5 w-5 text-indigo-400" />
                    <span className="text-lg font-mono font-medium tracking-wide">{phoneNumber}</span>
                  </div>
                  <div className="flex items-center gap-2 text-xs font-medium text-gray-400 group-hover:text-white transition-colors">
                    {copied ? (
                      <>
                        <Check className="h-4 w-4 text-green-400" />
                        <span className="text-green-400">{t('copied')}</span>
                      </>
                    ) : (
                      <>
                        <Copy className="h-4 w-4" />
                        <span>{t('copy')}</span>
                      </>
                    )}
                  </div>
                </button>
              </div>

              {isAuthenticated ? (
                <button 
                  onClick={handleConfirmBooking}
                  disabled={loading || (bookingType === 'single' && !selectedLectureId)}
                  className="w-full py-3 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-200 disabled:opacity-50 flex justify-center items-center"
                >
                  {loading ? <Loader className="animate-spin h-5 w-5" /> : t('confirmBooking')}
                </button>
              ) : (
                <div className="grid grid-cols-2 gap-4">
                   <Link to="/login" className="w-full">
                      <button className="w-full py-3 bg-white border border-gray-300 text-gray-700 font-bold rounded-xl hover:bg-gray-50 transition-colors flex items-center justify-center gap-2">
                        <LogIn className="h-4 w-4" /> {t('login')}
                      </button>
                   </Link>
                   <Link to="/signup" className="w-full">
                      <button className="w-full py-3 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-700 transition-colors flex items-center justify-center gap-2">
                        <UserPlus className="h-4 w-4" /> {t('signup')}
                      </button>
                   </Link>
                </div>
              )}
            </>
          ) : (
            <div className="text-center py-8">
               <div className="mx-auto h-16 w-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
                  <Check className="h-8 w-8 text-green-600" />
               </div>
               <h3 className="text-xl font-bold text-gray-900 mb-2">{t('requestSent')}</h3>
               <p className="text-gray-500 mb-6">
                  {t('requestSentDesc')}
               </p>
               <button 
                onClick={onClose}
                className="w-full py-3 bg-gray-100 text-gray-700 font-bold rounded-xl hover:bg-gray-200 transition-colors"
               >
                {t('close')}
               </button>
            </div>
          )}

        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { GraduationCap, LayoutDashboard, LogIn, UserPlus, LogOut, Globe } from 'lucide-react';
