  signup: (email: string, password: string, name: string) => Promise<void>;
  resetPassword: (email: string) => Promise<void>;
  updatePassword: (password: string) => Promise<void>;
  logout: () => Promise<void>;
  isAuthenticated: boolean;
  loading: boolean;
}

const AuthContext = createContext<AuthContextType>({
  user: null,
  login: async () => {},
  signup: async () => {},
  resetPassword: async () => {},
  updatePassword: async () => {},
  logout: async () => {},
  isAuthenticated: false,
  loading: false,
});

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  // Helper to construct User object from Supabase Auth + Profile
  const getUserProfile = async (authId: string, authEmail?: string, authMeta?: any): Promise<User | null> => {
      try {
        const { data: profile, error } = await supabase
            .from('profiles')
            .select('*')
            .eq('id', authId)
            .single();

        if (profile) {
            return {
                id: authId,
                name: profile.full_name || authMeta?.full_name || authEmail?.split('@')[0] || 'Student',
                email: profile.email || authEmail || '',
                role: profile.role as UserRole || 'student',
                xp: profile.xp || 0,
                level: profile.level || 1,
                credits: profile.credits || 0,
                subscriptionTier: 'free',
                bookedLectures: [],
                purchasedCourses: [],
                achievements: []
            };
        }

        // Self-Healing: If profile is missing but Auth exists, attempt to create it
        console.warn("Profile missing for existing auth user. Attempting to create...");
        const { data: newProfile, error: createError } = await supabase
            .from('profiles')
            .insert({
                id: authId,
                email: authEmail || '',
                full_name: authMeta?.full_name || authEmail?.split('@')[0],
                role: 'student'
            })
            .select()
            .single();

        if (newProfile) {
             console.log("Self-healing successful. Profile created.");
             return {
                id: authId,
                name: newProfile.full_name,
                email: newProfile.email,
                role: newProfile.role as UserRole,
                xp: 0, 
                level: 1, 
                credits: 0, 
                subscriptionTier: 'free', 
                bookedLectures: [], 
                purchasedCourses: [], 
                achievements: []
             };
        } else {
             console.error("Self-healing failed:", createError?.message);
        }

        // Ultimate Fallback
        return {
            id: authId,
            name: authMeta?.full_name || authEmail?.split('@')[0] || 'Student',
            email: authEmail || '',
            role: 'student', 
            xp: 0,
            level: 1,
            credits: 0,
            subscriptionTier: 'free',
            bookedLectures: [],
            purchasedCourses: [],
            achievements: []
        };
      } catch (e) {
          console.error("Critical Error fetching profile:", e);
          return null;
      }
  };

  useEffect(() => {
    const initAuth = async () => {
      if (isSupabaseConfigured() && supabase) {
        try {
          // 1. Check active session
          const { data: { session } } = await supabase.auth.getSession();
          if (session?.user) {
            const u = await getUserProfile(session.user.id, session.user.email, session.user.user_metadata);
            if (u) setUser(u);
          }

          // 2. Listen for auth changes
          supabase.auth.onAuthStateChange(async (event, session) => {
            if (event === 'SIGNED_IN' && session?.user) {
               // Prevent re-fetching if we already have the user (optimization)
               // But ensure we fetch if the user object is stale or null
               if (!user || user.id !== session.user.id) {
                   const u = await getUserProfile(session.user.id, session.user.email, session.user.user_metadata);
                   setUser(u);
               }
            } else if (event === 'SIGNED_OUT') {
               setUser(null);
            } else if (event === 'PASSWORD_RECOVERY') {
               if(session?.user) {
                   const u = await getUserProfile(session.user.id, session.user.email, session.user.user_metadata);
                   setUser(u);
               }
            }
          });

        } catch (err) {
            console.error("Supabase auth check failed", err);
        }
      } 

      // Fallback for Mock Mode
      if (!user) {
        const storedUser = localStorage.getItem('finki_user');
        if (storedUser) {
          setUser(JSON.parse(storedUser));
        }
      }

      setLoading(false);
    };

    initAuth();
  }, []); // Run once on mount

  const login = async (email: string, password?: string) => {
    setLoading(true);
    const cleanEmail = email.trim().toLowerCase();

    try {
        // Attempt Supabase Login
        if (isSupabaseConfigured() && supabase) {
          let sbError = null;
          let sbUser = null;

          try {
            const res = await supabase.auth.signInWithPassword({ 
                email: cleanEmail, 
                password: password || 'password' 
            });
            sbError = res.error;
            sbUser = res.data.user;
          } catch (err: any) {
            sbError = err;
          }

          if (sbError) {
               // Check if it's a demo account. If so, let it fall through to mock logic.
               const isDemoAccount = ['gorazd.g.petkovski05@gmail.com', 'nikola.jankoski@gmail.com', 'dragan@gmail.com'].includes(cleanEmail);

               if (!isDemoAccount) {
                   console.error("Supabase login error:", sbError.message);
                   throw new Error(sbError.message);
               }
          } else if (sbUser) {
               // SUCCESSFUL SUPABASE LOGIN
               console.log("Supabase login successful, fetching profile...");
               const u = await getUserProfile(sbUser.id, sbUser.email, sbUser.user_metadata);
               if (u) {
                   console.log("Profile fetched successfully. Role:", u.role);
                   setUser(u);
                   return; // Exit function successfully
               } 
               // If getUserProfile returns null (critical error), we might fall through or throw
               throw new Error("Could not load user profile.");
          }
        }

        // --- FALLBACK / DEMO ACCOUNTS ---

        const cleanPass = password?.trim();
        const isDemoAccount = ['gorazd.g.petkovski05@gmail.com', 'nikola.jankoski@gmail.com', 'dragan@gmail.com'].includes(cleanEmail);

        // If Supabase is configured and it's NOT a demo account, we do not allow mock login.
        if (isSupabaseConfigured() && !isDemoAccount) {
             throw new Error('Invalid login credentials or account does not exist.');
        }

        await new Promise(r => setTimeout(r, 600)); // Simulate net delay
        let newUser: User | null = null;

        if (cleanEmail === 'gorazd.g.petkovski05@gmail.com' && cleanPass === 'GorazdAdmin1!') {
          newUser = { ...MOCK_ADMIN };
        } else if (cleanEmail === 'nikola.jankoski@gmail.com' && cleanPass === 'Nikola123') {
          newUser = { ...MOCK_TEACHER_1 };
        } else if (cleanEmail === 'dragan@gmail.com' && cleanPass === 'Dragan123') {
          newUser = { ...MOCK_TEACHER_2 };
        } else if (!isSupabaseConfigured() && cleanPass && cleanPass.length >= 4) {
          newUser = { 
              ...MOCK_USER, 
              id: `u-${Date.now()}`,
              email: cleanEmail,
              name: cleanEmail.split('@')[0],
              role: 'student',
              xp: 0,
              level: 1,
              achievements: []
          };
        }

        if (newUser) {
          setUser(newUser);
          localStorage.setItem('finki_user', JSON.stringify(newUser));
        } else {
          throw new Error('Invalid email or password');
        }
    } catch (err) {
        throw err;
    } finally {
        setLoading(false);
    }
  };

  const signup = async (email: string, password: string, name: string) => {
    setLoading(true);
    const cleanEmail = email.trim();
    const cleanName = name.trim();

    try {
        if (isSupabaseConfigured() && supabase) {
          const { error } = await supabase.auth.signUp({
            email: cleanEmail,
            password,
            options: {
              data: { full_name: cleanName }
            }
          });

          if (error) {
              throw error;
          }
          return; 
        } 

        // Mock Signup
        const newUser: User = {
          id: `u-${Date.now()}`,
          name: cleanName,
          email: cleanEmail,
          role: 'student',
          xp: 0,
          level: 1,
          credits: 0,
          subscriptionTier: 'free',
          bookedLectures: [],
          purchasedCourses: [],
          achievements: []
        };
        setUser(newUser);
        localStorage.setItem('finki_user', JSON.stringify(newUser));
    } catch(err) {
        throw err;
    } finally {
        setLoading(false);
    }
  };

  const resetPassword = async (email: string) => {
    setLoading(true);
    const cleanEmail = email.trim();

    try {
        if (isSupabaseConfigured() && supabase) {
          const { error } = await supabase.auth.resetPasswordForEmail(cleanEmail, {
            redirectTo: window.location.origin + '/dashboard', 
          });
          if (error) {
            throw error;
          }
        } else {
          await new Promise(r => setTimeout(r, 1000));
        }
    } catch(err) {
        throw err;
    } finally {
        setLoading(false);
    }
  };

  const updatePassword = async (password: string) => {
    setLoading(true);
    try {
        if (isSupabaseConfigured() && supabase) {
            const { error } = await supabase.auth.updateUser({ password });
            if (error) throw error;
        } else {
            await new Promise(r => setTimeout(r, 1000));
        }
    } catch (e) {
        throw e;
    } finally {
        setLoading(false);
    }
  };

  const logout = async () => {
    // 1. Immediately Clear Client State (Optimistic Update)
    setUser(null);
    localStorage.removeItem('finki_user');

    // 2. Force Clear Supabase Persistence in LocalStorage
    // This is crucial if the network request fails/hangs or token is corrupt
    if (typeof window !== 'undefined') {
        Object.keys(localStorage).forEach(key => {
            if (key.startsWith('sb-') && key.endsWith('-auth-token')) {
                localStorage.removeItem(key);
            }
        });
    }

    // 3. Attempt Server-Side SignOut (Best Effort)
    if (isSupabaseConfigured() && supabase) {
        try {
            // We await but don't let it block the UI thread forever if network is bad
            await Promise.race([
                supabase.auth.signOut(),
                new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), 2000))
            ]);
        } catch (error) {
            console.warn("Logout: Server sign-out skipped or failed (Cleaned up locally)", error);
        }
    }
  };

  return (
    <AuthContext.Provider value={{ user, login, signup, resetPassword, updatePassword, logout, isAuthenticated: !!user, loading }}>
      {children}
    </AuthContext.Provider>
  );
};

