import React, { createContext, useContext, useState, useEffect } from 'react';
import { Course, LandingPageData, Booking, User, UserRole, Lecture } from '../types';
import { COURSES, MOCK_BOOKINGS, MOCK_USER } from '../constants';
import { supabase, isSupabaseConfigured } from '../supabaseClient';
import { useAuth } from './AuthContext';

interface DataContextType {
  courses: Course[];
  addCourse: (course: Course) => Promise<void>;
  bookings: Booking[];
  addBooking: (booking: Booking) => Promise<void>;
  updateBookingStatus: (id: string, status: 'approved' | 'rejected') => Promise<void>;
  landingPageData: LandingPageData;
  updateLandingPage: (data: Partial<LandingPageData>) => Promise<void>;
  users: User[];
  updateUserRole: (userId: string, role: UserRole) => Promise<void>;
  refreshData: () => Promise<void>;
}

const defaultLandingPage: LandingPageData = {
  heroTitle: "Master your subjects at",
  heroSubtitle: "Book expert professors for specific lectures or full courses. Flexible pricing designed for students.",
  statsStudents: "1,200+",
  statsProfessors: "50+",
  statsLectures: "3,500+",
  statsPassRate: "98%"
};

const DataContext = createContext<DataContextType>({
  courses: [],
  addCourse: async () => {},
  bookings: [],
  addBooking: async () => {},
  updateBookingStatus: async () => {},
  landingPageData: defaultLandingPage,
  updateLandingPage: async () => {},
  users: [],
  updateUserRole: async () => {},
  refreshData: async () => {},
});

export const DataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { user } = useAuth();
  const [courses, setCourses] = useState<Course[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [landingPageData, setLandingPageData] = useState<LandingPageData>(defaultLandingPage);

  // Load Data
  const refreshData = async () => {
    if (isSupabaseConfigured() && supabase) {
      try {
        // 1. Fetch Config
        const { data: configData } = await supabase
          .from('site_config')
          .select('value')
          .eq('key', 'landing_page')
          .single();
        if (configData) setLandingPageData(configData.value);

        // 2. Fetch Courses (Dynamic from DB)
        const { data: coursesData, error: coursesError } = await supabase
          .from('courses')
          .select('*, lectures(*)');

        if (!coursesError && coursesData && coursesData.length > 0) {
            const mappedCourses: Course[] = coursesData.map((c: any) => ({
                id: c.id,
                title: c.title,
                code: c.code,
                description: c.description,
                professorId: c.professor_id || 'p1', 
                professorName: c.professor_name,
                image: c.image,
                priceFull: c.price_full,
                priceSingle: c.price_single,
                lectures: c.lectures ? c.lectures.map((l: any) => ({
                    id: l.id,
                    title: l.title,
                    date: l.date,
                    duration: l.duration
                })) : []
            }));
            setCourses(mappedCourses);
        } else {
            // If DB is empty, we do NOT load mock courses because IDs will clash.
            // The seed script should handle initial data.
            setCourses([]);
        }

        // 3. Fetch Bookings
        let query = supabase.from('bookings').select('*').order('created_at', { ascending: false });
        const { data: bookingData, error: bookingError } = await query;

        if (bookingData) {
          const mappedBookings: Booking[] = bookingData.map((b: any) => ({
              id: b.id,
              userId: b.user_id,
              userEmail: b.user_email,
              courseId: b.course_id,
              courseTitle: b.course_title,
              type: b.type,
              status: b.status,
              date: b.date,
          }));
          setBookings(mappedBookings);
        }

        // 4. Fetch Users (Admin Only)
        if (user?.role === 'admin') {
            const { data: userData } = await supabase
              .from('profiles')
              .select('*')
              .order('created_at', { ascending: false });

            if (userData) {
                const mappedUsers: User[] = userData.map((u: any) => ({
                    id: u.id,
                    name: u.full_name || 'Student',
                    email: u.email,
                    role: u.role,
                    xp: u.xp,
                    level: u.level,
                    credits: u.credits,
                    subscriptionTier: 'free',
                    bookedLectures: [],
                    purchasedCourses: [],
                    achievements: []
                }));
                setUsers(mappedUsers);
            }
        }
      } catch (err) {
        console.error("Error refreshing data:", err);
      }
    } else {
      // Mock Data Persistence
      setCourses(COURSES);
      const storedBookings = localStorage.getItem('finki_bookings');
      if (storedBookings) {
        const parsed = JSON.parse(storedBookings);
        if (user?.role === 'student') {
            setBookings(parsed.filter((b: Booking) => b.userEmail === user.email));
        } else {
            setBookings(parsed);
        }
      } else {
         setBookings(MOCK_BOOKINGS);
      }

      if (user?.role === 'admin') setUsers([MOCK_USER]); 

      const storedConfig = localStorage.getItem('finki_config');
      if (storedConfig) setLandingPageData(JSON.parse(storedConfig));
    }
  };

  useEffect(() => {
    refreshData();
  }, [user]);

  const addCourse = async (course: Course) => {
    // Prevent mock users from writing to DB
    const isRealUser = user?.id && user.id.length > 20; // UUID length check

    if (isSupabaseConfigured() && supabase && isRealUser) {

        // FIX: Blob URLs crash the DB. Revert to placeholder if real URL not present.
        let safeImage = course.image;
        if (safeImage.startsWith('blob:')) {
            // Using a random placeholder because we don't have Storage setup in this context
            safeImage = `https://source.unsplash.com/random/800x600?study,${course.code}`;
        }

        const { data: courseData, error: courseError } = await supabase.from('courses').insert({
            title: course.title,
            code: course.code,
            description: course.description,
            professor_id: course.professorId, 
            image: safeImage,
            price_full: course.priceFull,
            price_single: course.priceSingle
        }).select().single();

        if (courseError) {
            console.error("Supabase Add Course Error:", courseError);
            throw new Error(courseError.message);
        }

        if (courseData && course.lectures.length > 0) {
            const lectureInserts = course.lectures.map(l => ({
                course_id: courseData.id,
                title: l.title,
                date: l.date,
                duration: l.duration
            }));
            const { error: lecError } = await supabase.from('lectures').insert(lectureInserts);
            if (lecError) console.error("Error inserting lectures:", lecError);
        }
        await refreshData();
    } else {
        setCourses(prev => [...prev, course]);
    }
  };

  const addBooking = async (booking: Booking) => {
    // Prevent mock users from writing to DB
    const isRealUser = user?.id && user.id.length > 20; // UUID length check

    if (isSupabaseConfigured() && supabase && isRealUser) {
       // Validate Session before request to avoid RLS errors
       const { data: { session } } = await supabase.auth.getSession();
       if (!session) {
           throw new Error("Session expired. Please login again.");
       }

       // We do NOT send user_id. We let the DB default to auth.uid()
       const { error } = await supabase.from('bookings').insert({
         // user_id: user?.id,  <-- REMOVED to let DB handle it securely
         user_email: user?.email,
         course_id: booking.courseId, 
         course_title: booking.courseTitle,
         type: booking.type,
         status: 'pending',
         date: booking.date
       });

       if (error) {
           console.error("Booking Error:", error);
           throw new Error(`Booking failed: ${error.message}`); 
       }

       // Optimistic Update or Refresh
       await refreshData();
    } else {
       // Mock Logic
       const newBookings = [booking, ...bookings];
       setBookings(newBookings);
       const allBookings = JSON.parse(localStorage.getItem('finki_bookings') || JSON.stringify(MOCK_BOOKINGS));
       localStorage.setItem('finki_bookings', JSON.stringify([booking, ...allBookings]));
       await new Promise(r => setTimeout(r, 500)); // Sim delay
    }
  };

  const updateBookingStatus = async (id: string, status: 'approved' | 'rejected') => {
    // Regex check for standard UUID format (8-4-4-4-12 hex chars)
    const isUUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id);

    if (isSupabaseConfigured() && supabase && isUUID) {
        const { error } = await supabase.from('bookings').update({ status }).eq('id', id);
        if (error) throw error;
        await refreshData();
    } else {
        // Fallback for mock IDs or when working in hybrid/mock mode
        const updated = bookings.map(b => b.id === id ? { ...b, status } : b);
        setBookings(updated);

        // Persist to local storage if present
        const stored = localStorage.getItem('finki_bookings');
        if (stored) {
            const allBookings = JSON.parse(stored);
            const updatedAll = allBookings.map((b: Booking) => b.id === id ? { ...b, status } : b);
            localStorage.setItem('finki_bookings', JSON.stringify(updatedAll));
        }
    }
  };

  const updateLandingPage = async (data: Partial<LandingPageData>) => {
    const newData = { ...landingPageData, ...data };
    setLandingPageData(newData);

    if (isSupabaseConfigured() && supabase) {
        await supabase.from('site_config').upsert({
            key: 'landing_page',
            value: newData
        }, { onConflict: 'key' });
    } else {
        localStorage.setItem('finki_config', JSON.stringify(newData));
    }
  };

  const updateUserRole = async (userId: string, role: UserRole) => {
      // Check if real UUID
      const isUUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(userId);

      if (isSupabaseConfigured() && supabase && isUUID) {
          const { error } = await supabase.from('profiles').update({ role }).eq('id', userId);
          if (error) throw error;
          await refreshData();
      } else {
          setUsers(users.map(u => u.id === userId ? { ...u, role } : u));
      }
  };

  return (
    <DataContext.Provider value={{ 
      courses, 
      addCourse, 
      bookings, 
      addBooking, 
      updateBookingStatus,
      landingPageData, 
      updateLandingPage,
      users, 
      updateUserRole,
      refreshData
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => useContext(DataContext);

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, UserRole } from '../types';
import { supabase } from '../supabaseClient';

interface AuthContextType {
  user: User | null;
  login: (email: string, password?: string) => Promise<void>;
  signup: (email: string, password: string, name: string) => Promise<void>;
  resetPassword: (email: string) => Promise<void>;
  updatePassword: (password: string) => Promise<void>;
  logout: () => Promise<void>;
  isAuthenticated: boolean;
  loading: boolean;
}

const AuthContext = createContext<AuthContextType>({
  user: null,
  login: async () => {},
  signup: async () => {},
  resetPassword: async () => {},
  updatePassword: async () => {},
  logout: async () => {},
  isAuthenticated: false,
  loading: false,
});

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  const userIdRef = useRef<string | null>(null);

  useEffect(() => {
    userIdRef.current = user?.id || null;
  }, [user]);

  const getUserProfile = async (authId: string, authEmail?: string, authMeta?: any): Promise<User | null> => {
      try {
        const { data: profile } = await supabase
            .from('profiles')
            .select('*')
            .eq('id', authId)
            .single();

        if (profile) {
            return {
                id: authId,
                name: profile.full_name || authMeta?.full_name || authEmail?.split('@')[0] || 'Student',
                email: profile.email || authEmail || '',
                role: profile.role as UserRole || 'student',
                xp: profile.xp || 0,
                level: profile.level || 1,
                credits: profile.credits || 0,
                subscriptionTier: 'free',
                bookedLectures: [],
                purchasedCourses: [],
                achievements: []
            };
        }

        // Self-Healing
        console.warn("Profile missing for existing auth user. Attempting to create...");
        const { data: newProfile, error: createError } = await supabase
            .from('profiles')
            .insert({
                id: authId,
                email: authEmail || '',
                full_name: authMeta?.full_name || authEmail?.split('@')[0],
                role: 'student'
            })
            .select()
            .single();

        if (newProfile) {
             return {
                id: authId,
                name: newProfile.full_name,
                email: newProfile.email,
                role: newProfile.role as UserRole,
                xp: 0, 
                level: 1, 
                credits: 0, 
                subscriptionTier: 'free', 
                bookedLectures: [], 
                purchasedCourses: [], 
                achievements: []
             };
        } else {
             console.error("Self-healing failed:", createError?.message);
             return null;
        }
      } catch (e) {
          console.error("Critical Error fetching profile:", e);
          return null;
      }
  };

  useEffect(() => {
    const initAuth = async () => {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
          const u = await getUserProfile(session.user.id, session.user.email, session.user.user_metadata);
          if (u) setUser(u);
        }

        supabase.auth.onAuthStateChange(async (event, session) => {
          if (event === 'SIGNED_IN' && session?.user) {
             if (userIdRef.current !== session.user.id) {
                 const u = await getUserProfile(session.user.id, session.user.email, session.user.user_metadata);
                 setUser(u);
             }
          } else if (event === 'SIGNED_OUT') {
             setUser(null);
             userIdRef.current = null;
          }
        });
      } catch (err) {
          console.error("Supabase auth check failed", err);
      } finally {
          setLoading(false);
      }
    };

    initAuth();
  }, []);

  const login = async (email: string, password?: string) => {
    setLoading(true);
    const cleanEmail = email.trim().toLowerCase();

    try {
        await supabase.auth.signOut().catch(() => {});

        const { data, error } = await supabase.auth.signInWithPassword({ 
            email: cleanEmail, 
            password: password || 'password' 
        });

        if (error) throw error;

        if (data.user) {
           const u = await getUserProfile(data.user.id, data.user.email, data.user.user_metadata);
           if (u) {
               setUser(u);
               return;
           } 
           throw new Error("Could not load user profile.");
        }
    } catch (err) {
        throw err;
    } finally {
        setLoading(false);
    }
  };

  const signup = async (email: string, password: string, name: string) => {
    setLoading(true);
    const cleanEmail = email.trim();
    const cleanName = name.trim();

    try {
        const { error } = await supabase.auth.signUp({
            email: cleanEmail,
            password,
            options: {
                data: { full_name: cleanName }
            }
        });

        if (error) throw error;
    } catch(err) {
        throw err;
    } finally {
        setLoading(false);
    }
  };

  const resetPassword = async (email: string) => {
    setLoading(true);
    try {
        const { error } = await supabase.auth.resetPasswordForEmail(email.trim(), {
            redirectTo: window.location.origin + '/dashboard', 
        });
        if (error) throw error;
    } catch(err) {
        throw err;
    } finally {
        setLoading(false);
    }
  };

  const updatePassword = async (password: string) => {
    setLoading(true);
    try {
        const { error } = await supabase.auth.updateUser({ password });
        if (error) throw error;
    } catch (e) {
        throw e;
    } finally {
        setLoading(false);
    }
  };

  const logout = async () => {
    setUser(null);
    userIdRef.current = null;
    try {
        await Promise.race([
            supabase.auth.signOut(),
            new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), 2000))
        ]);
    } catch (error) {
        console.warn("Logout: Sign-out skipped or failed", error);
    } finally {
        if (typeof window !== 'undefined') {
            Object.keys(localStorage).forEach(key => {
                if (key.startsWith('sb-') && key.endsWith('-auth-token')) {
                    localStorage.removeItem(key);
                }
            });
        }
    }
  };

  return (
    <AuthContext.Provider value={{ user, login, signup, resetPassword, updatePassword, logout, isAuthenticated: !!user, loading }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);

