import React, { useState } from 'react';
import { CourseCard } from '../components/CourseCard';
import { Search, Filter } from 'lucide-react';
import { useData } from '../contexts/DataContext';
import { useLanguage } from '../contexts/LanguageContext';

export const CoursesPage: React.FC = () => {
  const { courses } = useData();
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedUniversity, setSelectedUniversity] = useState('All');
  const { t } = useLanguage();

  // Extract unique universities, ensuring 'FINKI' is always present along with 'All'
  const availableUnis = Array.from(new Set(courses.map(c => c.university).filter(Boolean))) as string[];
  const universities = ['All', 'FINKI', ...availableUnis.filter(u => u !== 'FINKI')];

  const filteredCourses = courses.filter(c => {
    const matchesSearch = c.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          c.code.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesUni = selectedUniversity === 'All' || c.university === selectedUniversity;

    return matchesSearch && matchesUni;
  });

  return (
    <div className="min-h-screen bg-gray-50 py-12">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex flex-col gap-6 mb-8">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div>
                <h1 className="text-3xl font-bold text-gray-900">{t('availableCourses')}</h1>
                <p className="mt-2 text-gray-600">{t('selectSubject')}</p>
            </div>

            <div className="relative">
                <Search className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
                <input 
                type="text" 
                placeholder={t('searchPlaceholder')}
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-10 pr-4 py-2.5 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500 w-full md:w-64"
                />
            </div>
            </div>

            {/* University Filter */}
            <div className="flex items-center gap-3 overflow-x-auto pb-2 scrollbar-hide">
                <div className="flex items-center gap-2 text-sm text-gray-500 font-medium mr-2">
                    <Filter className="h-4 w-4" /> Filter:
                </div>
                {universities.map(uni => (
                    <button
                        key={uni}
                        onClick={() => setSelectedUniversity(uni)}
                        className={`px-4 py-2 rounded-full text-sm font-bold whitespace-nowrap transition-all ${
                            selectedUniversity === uni 
                            ? 'bg-indigo-600 text-white shadow-md shadow-indigo-200' 
                            : 'bg-white text-gray-600 border border-gray-200 hover:bg-gray-50'
                        }`}
                    >
                        {uni}
                    </button>
                ))}
            </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {filteredCourses.map(course => (
            <CourseCard 
              key={course.id} 
              course={course} 
            />
          ))}
        </div>

        {filteredCourses.length === 0 && (
          <div className="text-center py-20 bg-white rounded-3xl border border-dashed border-gray-200">
            <p className="text-gray-500 font-medium">{t('noCoursesFound')}</p>
            {selectedUniversity !== 'All' && selectedUniversity !== 'FINKI' && (
                <button 
                    onClick={() => setSelectedUniversity('All')}
                    className="mt-4 text-indigo-600 font-bold hover:underline"
                >
                    View all universities
                </button>
            )}
            {/* If FINKI is selected but empty, show a message suggesting to add courses via Admin */}
            {selectedUniversity === 'FINKI' && (
                <p className="text-sm text-gray-400 mt-2">New courses for FINKI coming soon.</p>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

