-- We need to create dummy professor records linked to dummy profiles if they don't exist
-- For simplicity, we will assume manual creation via app for new professors, 
-- but let's create placeholders for the existing mock courses if needed.

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Course, LandingPageData, Booking, User, UserRole, Professor } from '../types';
import { supabase } from '../supabaseClient';
import { useAuth } from './AuthContext';
import { useNotification } from './NotificationContext';

interface DataContextType {
  courses: Course[];
  addCourse: (course: Course) => Promise<void>;
  uploadCourseImage: (file: File) => Promise<string>;
  bookings: Booking[];
  addBooking: (booking: Booking, pricePaid: number) => Promise<void>;
  updateBookingStatus: (id: string, status: 'approved' | 'rejected') => Promise<void>;
  landingPageData: LandingPageData;
  updateLandingPage: (data: Partial<LandingPageData>) => Promise<void>;
  users: User[];
  professors: Professor[];
  updateUserRole: (userId: string, role: UserRole) => Promise<void>;
  updateProfessorDetails: (prof: Professor) => Promise<void>;
  refreshData: () => Promise<void>;
}

const defaultLandingPage: LandingPageData = {
  heroTitle: "Master your subjects at",
  heroSubtitle: "Book expert professors for specific lectures or full courses. Flexible pricing designed for students.",
  statsStudents: "1,200+",
  statsProfessors: "50+",
  statsLectures: "3,500+",
  statsPassRate: "98%"
};

const DataContext = createContext<DataContextType>({
  courses: [],
  addCourse: async () => {},
  uploadCourseImage: async () => "",
  bookings: [],
  addBooking: async () => {},
  updateBookingStatus: async () => {},
  landingPageData: defaultLandingPage,
  updateLandingPage: async () => {},
  users: [],
  professors: [],
  updateUserRole: async () => {},
  updateProfessorDetails: async () => {},
  refreshData: async () => {},
});

export const DataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { user, refreshUser } = useAuth();
  const { notify } = useNotification();
  const [courses, setCourses] = useState<Course[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [professors, setProfessors] = useState<Professor[]>([]);
  const [landingPageData, setLandingPageData] = useState<LandingPageData>(defaultLandingPage);

  const refreshData = async () => {
      try {
        // 1. Fetch Config
        const { data: configData } = await supabase.from('site_config').select('value').eq('key', 'landing_page').single();
        if (configData) setLandingPageData(configData.value);

        // 2. Fetch Professors
        const { data: profData } = await supabase.from('professors').select('*');
        const mappedProfs: Professor[] = profData ? profData.map((p: any) => ({
            id: p.id,
            name: p.name,
            specialty: p.specialty,
            avatar: p.avatar,
            rating: Number(p.rating)
        })) : [];
        setProfessors(mappedProfs);

        // 3. Fetch Courses
        const { data: coursesData, error: coursesError } = await supabase
          .from('courses')
          .select('*, lectures(*)');

        if (!coursesError && coursesData) {
            const mappedCourses: Course[] = coursesData.map((c: any) => {
                const prof = mappedProfs.find(p => p.id === c.professor_id);
                return {
                    id: c.id,
                    title: c.title,
                    code: c.code,
                    description: c.description,
                    professorId: c.professor_id, 
                    professorName: prof?.name || 'Unknown',
                    image: c.image,
                    university: c.university || 'FINKI',
                    priceFull: c.price_full,
                    priceSingle: c.price_single,
                    lectures: c.lectures ? c.lectures.map((l: any) => ({
                        id: l.id,
                        title: l.title,
                        date: l.date,
                        duration: l.duration
                    })) : []
                };
            });
            setCourses(mappedCourses);
        }

        // 4. Fetch Bookings
        const { data: bookingData } = await supabase.from('bookings').select('*').order('created_at', { ascending: false });
        if (bookingData) {
          setBookings(bookingData.map((b: any) => ({
              id: b.id,
              userId: b.user_id,
              userEmail: b.user_email,
              courseId: b.course_id,
              courseTitle: b.course_title,
              type: b.type,
              status: b.status,
              date: b.date,
          })));
        }

        // 5. Fetch Users (Admin)
        if (user?.role === 'admin') {
            const { data: userData } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
            if (userData) {
                setUsers(userData.map((u: any) => ({
                    id: u.id,
                    name: u.full_name || 'Student',
                    email: u.email,
                    role: u.role,
                    xp: u.xp,
                    level: u.level,
                    credits: u.credits,
                    subscriptionTier: 'free',
                    bookedLectures: [],
                    purchasedCourses: [],
                    achievements: []
                })));
            }
        }
      } catch (err) {
        console.error("Error refreshing data:", err);
      }
  };

  useEffect(() => {
    refreshData();
  }, [user]);

  // --- XP Logic ---
  // Level 1: 0 - 499 XP
  // Level 2: 500 - 1999 XP
  // Level 3: 2000+ XP
  // 
  // Reward Structure:
  // Single Lecture: 200 (Request) + 300 (Approved) = 500 XP.
  // Full Course: 500 (Request) + 1000 (Approved) = 1500 XP.
  // 
  // Math: 
  // 1 Course (1500) + 1 Lecture (500) = 2000 XP (Level 3).
  // 2 Courses (3000) = 3000 XP (Level 3).
  const awardXP = async (userId: string, amount: number) => {
    try {
        const { data: profile } = await supabase.from('profiles').select('xp, level').eq('id', userId).single();
        if (!profile) return;

        const newXP = (profile.xp || 0) + amount;
        // Formula: Level = floor(sqrt(XP / 500)) + 1
        const newLevel = Math.floor(Math.sqrt(newXP / 500)) + 1;

        await supabase.from('profiles').update({ xp: newXP, level: newLevel }).eq('id', userId);

        if (newLevel > (profile.level || 1) && user?.id === userId) {
            notify('Level Up!', `You reached Level ${newLevel}! Discount Unlocked?`, 'achievement');
        }
    } catch (e) { console.error(e); }
  };

  const uploadCourseImage = async (file: File): Promise<string> => {
    try {
        const fileExt = file.name.split('.').pop();
        const fileName = `${Math.random().toString(36).substring(2)}.${fileExt}`;
        const { error } = await supabase.storage.from('course-images').upload(fileName, file);
        if (error) throw error;
        const { data } = supabase.storage.from('course-images').getPublicUrl(fileName);
        return data.publicUrl;
    } catch (error: any) {
        throw new Error("Failed to upload image.");
    }
  };

  const addCourse = async (course: Course) => {
    const { data: courseData, error } = await supabase.from('courses').insert({
        title: course.title,
        code: course.code,
        description: course.description,
        professor_id: course.professorId, 
        image: course.image,
        university: course.university,
        price_full: course.priceFull,
        price_single: course.priceSingle
    }).select().single();

    if (error) throw new Error(error.message);

    if (courseData && course.lectures.length > 0) {
        const lectureInserts = course.lectures.map(l => ({
            course_id: courseData.id,
            title: l.title,
            date: l.date || new Date().toISOString(), 
            duration: l.duration
        }));
        await supabase.from('lectures').insert(lectureInserts);
    }
    await refreshData();
  };

  const addBooking = async (booking: Booking, pricePaid: number) => {
     const { error } = await supabase.from('bookings').insert({
       user_email: user?.email,
       course_id: booking.courseId, 
       course_title: booking.courseTitle,
       type: booking.type,
       status: 'pending',
       date: booking.date,
       price_paid: pricePaid
     });

     if (error) throw new Error(`Booking failed: ${error.message}`); 

     // AWARD XP: Request
     // Single: 200 XP, Full: 500 XP
     const xpAmount = booking.type === 'full' ? 500 : 200;
     if (user?.id) {
         await awardXP(user.id, xpAmount);
         if (refreshUser) refreshUser(); 
     }
     await refreshData();
  };

  const updateBookingStatus = async (id: string, status: 'approved' | 'rejected') => {
    const { data: bookingData } = await supabase.from('bookings').select('user_id, type').eq('id', id).single();
    const { error } = await supabase.from('bookings').update({ status }).eq('id', id);
    if (error) throw error;

    // AWARD XP: Approved
    // Single: +300 XP (Total 500). Full: +1000 XP (Total 1500).
    if (status === 'approved' && bookingData?.user_id) {
        const xpAmount = bookingData.type === 'full' ? 1000 : 300;
        await awardXP(bookingData.user_id, xpAmount);
    }
    await refreshData();
  };

  const updateLandingPage = async (data: Partial<LandingPageData>) => {
    const newData = { ...landingPageData, ...data };
    setLandingPageData(newData);
    await supabase.from('site_config').upsert({ key: 'landing_page', value: newData }, { onConflict: 'key' });
  };

  const updateUserRole = async (userId: string, role: UserRole) => {
      // 1. Update Profile Role
      const { error } = await supabase.from('profiles').update({ role }).eq('id', userId);
      if (error) throw error;

      // 2. Handle Professor Record
      if (role === 'teacher') {
          // Check if exists
          const { data: existing } = await supabase.from('professors').select('id').eq('id', userId).single();
          if (!existing) {
             // Create default professor record
             const { data: userProfile } = await supabase.from('profiles').select('full_name').eq('id', userId).single();
             await supabase.from('professors').insert({
                 id: userId,
                 name: userProfile?.full_name || 'Professor',
                 specialty: 'New Lecturer',
                 avatar: 'https://ui-avatars.com/api/?name=P&background=random',
                 rating: 5.0
             });
          }
      } else {
          // Remove from professors if demoted
          await supabase.from('professors').delete().eq('id', userId);
      }

      await refreshData();
  };

  const updateProfessorDetails = async (prof: Professor) => {
      const { error } = await supabase.from('professors').update({
          name: prof.name,
          specialty: prof.specialty,
          avatar: prof.avatar,
          rating: prof.rating
      }).eq('id', prof.id);

      if (error) throw error;
      await refreshData();
  }

  return (
    <DataContext.Provider value={{ 
      courses, addCourse, uploadCourseImage,
      bookings, addBooking, updateBookingStatus,
      landingPageData, updateLandingPage,
      users, professors, updateUserRole, updateProfessorDetails,
      refreshData
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => useContext(DataContext);

