  heroTitle: string;
  heroSubtitle: string;
  statsStudents: string;
  statsProfessors: string;
  statsLectures: string;
  statsPassRate: string;
}

export interface Notification {
  id: string;
  title: string;
  message: string;
  type: 'success' | 'info' | 'achievement';
}

