  "statsStudents": "1,200+",
  "statsProfessors": "50+",
  "statsLectures": "3,500+",
  "statsPassRate": "98%"
}'::jsonb)
on conflict (key) do nothing;

-- 9. ACHIEVEMENTS
create table public.achievements (
  id uuid default uuid_generate_v4() primary key,
  title text not null,
  description text,
  icon text not null,
  xp_reward integer default 100
);

-- 10. STORAGE FOR IMAGES
insert into storage.buckets (id, name, public) 
values ('course-images', 'course-images', true)
on conflict (id) do nothing;

-- 11. SECURITY
alter table public.profiles enable row level security;
alter table public.professors enable row level security;
alter table public.courses enable row level security;
alter table public.lectures enable row level security;
alter table public.bookings enable row level security;
alter table public.site_config enable row level security;

-- HELPER FUNCTION: is_admin()
create or replace function public.is_admin()
returns boolean as $$
begin
  return exists (
    select 1 from public.profiles
    where id = auth.uid() and role = 'admin'::public.user_role
  );
end;
$$ language plpgsql security definer set search_path = public;

-- POLICIES

-- Profiles
create policy "Public profiles are viewable by everyone" on public.profiles for select using (true);
create policy "Users can update own profile" on public.profiles for update using (auth.uid() = id);
create policy "Admins can update any profile" on public.profiles for update using (public.is_admin());

-- Professors
create policy "Professors viewable by everyone" on public.professors for select using (true);
create policy "Admins manage professors" on public.professors for all using (public.is_admin());

-- Courses
create policy "Courses viewable by everyone" on public.courses for select using (true);
create policy "Admins/Teachers insert courses" on public.courses for insert with check (
  public.is_admin() or exists (select 1 from public.profiles where id = auth.uid() and role = 'teacher'::public.user_role)
);
create policy "Admins/Teachers update courses" on public.courses for update using (
  public.is_admin() or exists (select 1 from public.profiles where id = auth.uid() and role = 'teacher'::public.user_role)
);

-- Lectures
create policy "Lectures viewable by everyone" on public.lectures for select using (true);
create policy "Admins/Teachers manage lectures" on public.lectures for all using (
  public.is_admin() or exists (select 1 from public.profiles where id = auth.uid() and role = 'teacher'::public.user_role)
);

-- Bookings
create policy "Users view own bookings" on public.bookings for select using (auth.uid() = user_id);
create policy "Teachers/Admins view all bookings" on public.bookings for select using (true); 
create policy "Authenticated users insert bookings" on public.bookings for insert with check (auth.uid() = user_id);
create policy "Admins/Teachers update bookings" on public.bookings for update using (
  public.is_admin() or exists (select 1 from public.profiles where id = auth.uid() and role = 'teacher'::public.user_role)
);

-- Config
create policy "Config viewable by everyone" on public.site_config for select using (true);
create policy "Admins update config" on public.site_config for update using (public.is_admin());

-- Storage Policies
drop policy if exists "Public Access to Course Images" on storage.objects;
drop policy if exists "Auth Users Upload Images" on storage.objects;
create policy "Public Access to Course Images" on storage.objects for select using ( bucket_id = 'course-images' );
create policy "Auth Users Upload Images" on storage.objects for insert with check ( bucket_id = 'course-images' and auth.role() = 'authenticated' );

-- 12. AUTOMATIC PROFILE CREATION
create or replace function public.handle_new_user()
returns trigger as $$
begin
  insert into public.profiles (id, email, full_name, role)
  values (
    new.id, 
    new.email, 
    new.raw_user_meta_data->>'full_name', 
    'student'
  );
  return new;
end;
$$ language plpgsql security definer set search_path = public;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();

-- 13. DATA RECOVERY & SEEDING

-- Restore Profiles
insert into public.profiles (id, email, full_name, role)
select id, email, raw_user_meta_data->>'full_name', 'student'::public.user_role
from auth.users
where id not in (select id from public.profiles);

