  addProfessor: (prof: Omit<Professor, 'id'>) => Promise<void>;
  updateProfessorDetails: (prof: Professor) => Promise<void>;
  deleteProfessor: (id: string) => Promise<void>;
  refreshData: () => Promise<void>;
  myProfessorProfile: Professor | undefined; // The professor record linked to the logged in user
}

