                                        <Users className="h-5 w-5 text-indigo-600" /> My Students
                                    </h3>
                                </div>
                                <div className="overflow-x-auto">
                                    <table className="w-full text-left">
                                        <thead className="bg-gray-50">
                                            <tr>
                                                <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Student Email</th>
                                                <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Course</th>
                                                <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Type</th>
                                                <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Status</th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-gray-100">
                                            {myBookings.map(b => (
                                                <tr key={b.id} className="hover:bg-gray-50">
                                                    <td className="px-6 py-4 font-medium text-gray-900">{b.userEmail}</td>
                                                    <td className="px-6 py-4 text-sm text-gray-500">{b.courseTitle}</td>
                                                    <td className="px-6 py-4 text-xs font-bold uppercase">{b.type}</td>
                                                    <td className="px-6 py-4">
                                                        <span className={`px-2 py-1 rounded-full text-xs font-bold ${b.status === 'approved' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'}`}>
                                                            {b.status}
                                                        </span>
                                                    </td>
                                                </tr>
                                            ))}
                                            {myBookings.length === 0 && (
                                                <tr><td colSpan={4} className="p-8 text-center text-gray-400">No students enrolled yet.</td></tr>
                                            )}
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                        )}

                        {(user.role !== 'admin') && (
                            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6">
                                <h3 className="font-bold text-lg text-gray-900 mb-4 flex items-center gap-2">
                                <Activity className="h-5 w-5 text-indigo-600" /> {t('recentActivity')}
                                </h3>
                                <div className="space-y-4">
                                {myBookings.length === 0 ? <p className="text-gray-500 text-center py-4">No recent bookings.</p> : (
                                    myBookings.slice(0, 3).map(booking => (
                                        <div key={booking.id} className="flex items-center justify-between p-4 bg-gray-50 rounded-xl border border-gray-100">
                                            <div>
                                                <h4 className="font-bold text-gray-900">{booking.courseTitle}</h4>
                                                <p className="text-sm text-gray-600">{new Date(booking.date).toLocaleDateString()}</p>
                                            </div>
                                            <div><span className={`px-3 py-1 rounded-full text-xs font-bold ${booking.status === 'approved' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'}`}>{booking.status}</span></div>
                                        </div>
                                    ))
                                )}
                                </div>
                            </div>
                        )}
                   </>
                )}

                {/* CALENDAR TAB */}
                {activeTab === 'calendar' && (
                    <SquareCalendar bookings={myBookings} />
                )}
            </div>

            <div className="space-y-8">
                <AnalyticsCard role={user.role} />
                <AiTutor />
            </div>
        </div>
      </div>
    </div>
  );
};

