import React, { createContext, useContext, useState, useEffect } from 'react';
import { Course, LandingPageData, Booking, User, UserRole, Professor } from '../types';
import { supabase } from '../supabaseClient';
import { useAuth } from './AuthContext';
import { useNotification } from './NotificationContext';

interface DataContextType {
  courses: Course[];
  addCourse: (course: Course) => Promise<void>;
  uploadCourseImage: (file: File) => Promise<string>;
  bookings: Booking[];
  addBooking: (booking: Booking, pricePaid: number) => Promise<void>;
  updateBookingStatus: (id: string, status: 'approved' | 'rejected') => Promise<void>;
  landingPageData: LandingPageData;
  updateLandingPage: (data: Partial<LandingPageData>) => Promise<void>;
  users: User[];
  professors: Professor[];
  updateUserRole: (userId: string, role: UserRole) => Promise<void>;
  addProfessor: (prof: Omit<Professor, 'id'>) => Promise<void>;
  updateProfessorDetails: (prof: Professor) => Promise<void>;
  deleteProfessor: (id: string) => Promise<void>;
  refreshData: () => Promise<void>;
  myProfessorProfile: Professor | undefined; // The professor record linked to the logged in user
}

const defaultLandingPage: LandingPageData = {
  heroTitle: "Master your subjects at",
  heroSubtitle: "Book expert professors for specific lectures or full courses. Flexible pricing designed for students.",
  statsStudents: "1,200+",
  statsProfessors: "50+",
  statsLectures: "3,500+",
  statsPassRate: "98%"
};

const DataContext = createContext<DataContextType>({
  courses: [],
  addCourse: async () => {},
  uploadCourseImage: async () => "",
  bookings: [],
  addBooking: async () => {},
  updateBookingStatus: async () => {},
  landingPageData: defaultLandingPage,
  updateLandingPage: async () => {},
  users: [],
  professors: [],
  updateUserRole: async () => {},
  addProfessor: async () => {},
  updateProfessorDetails: async () => {},
  deleteProfessor: async () => {},
  refreshData: async () => {},
  myProfessorProfile: undefined,
});

export const DataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { user, refreshUser } = useAuth();
  const { notify } = useNotification();
  const [courses, setCourses] = useState<Course[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [professors, setProfessors] = useState<Professor[]>([]);
  const [landingPageData, setLandingPageData] = useState<LandingPageData>(defaultLandingPage);

  // Improved matching logic: Case insensitive and trimmed
  const myProfessorProfile = professors.find(p => 
      p.email?.trim().toLowerCase() === user?.email?.trim().toLowerCase()
  );

  const refreshData = async () => {
      try {
        // 1. Fetch Config
        const { data: configData } = await supabase.from('site_config').select('value').eq('key', 'landing_page').single();
        if (configData) setLandingPageData(configData.value);

        // 2. Fetch Professors
        const { data: profData } = await supabase.from('professors').select('*');
        const mappedProfs: Professor[] = profData ? profData.map((p: any) => ({
            id: p.id,
            name: p.name,
            email: p.email,
            customTag: p.custom_tag,
            specialty: p.specialty,
            avatar: p.avatar,
            rating: Number(p.rating)
        })) : [];
        setProfessors(mappedProfs);

        // 3. Fetch Courses
        const { data: coursesData, error: coursesError } = await supabase
          .from('courses')
          .select('*, lectures(*)');

        if (!coursesError && coursesData) {
            const mappedCourses: Course[] = coursesData.map((c: any) => {
                const prof = mappedProfs.find(p => p.id === c.professor_id);
                return {
                    id: c.id,
                    title: c.title,
                    code: c.code,
                    description: c.description,
                    professorId: c.professor_id, 
                    professorName: prof?.name || 'Unknown',
                    image: c.image,
                    university: c.university || 'FINKI',
                    priceFull: c.price_full,
                    priceSingle: c.price_single,
                    lectures: c.lectures ? c.lectures.map((l: any) => ({
                        id: l.id,
                        title: l.title,
                        date: l.date,
                        duration: l.duration
                    })) : []
                };
            });
            setCourses(mappedCourses);
        }

        // 4. Fetch Bookings (Join with Profiles to get Name)
        const { data: bookingData } = await supabase
            .from('bookings')
            .select('*, profiles(full_name)')
            .order('created_at', { ascending: false });

        if (bookingData) {
          setBookings(bookingData.map((b: any) => ({
              id: b.id,
              userId: b.user_id,
              userName: b.profiles?.full_name || 'Student', // Map full_name from joined profiles table
              userEmail: b.user_email,
              courseId: b.course_id,
              courseTitle: b.course_title,
              type: b.type,
              status: b.status,
              date: b.date,
              pricePaid: b.price_paid
          })));
        }

        // 5. Fetch Users (Admin)
        if (user?.role === 'admin') {
            const { data: userData } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
            if (userData) {
                setUsers(userData.map((u: any) => ({
                    id: u.id,
                    name: u.full_name || 'Student',
                    email: u.email,
                    role: u.role,
                    xp: u.xp,
                    level: u.level,
                    credits: u.credits,
                    subscriptionTier: 'free',
                    bookedLectures: [],
                    purchasedCourses: [],
                    achievements: []
                })));
            }
        }
      } catch (err) {
        console.error("Error refreshing data:", err);
      }
  };

  useEffect(() => {
    refreshData();
  }, [user]);

  // --- XP Logic ---
  const awardXP = async (userId: string, amount: number) => {
    try {
        const { data: profile } = await supabase.from('profiles').select('xp, level').eq('id', userId).single();
        if (!profile) return;

        const newXP = (profile.xp || 0) + amount;
        // Formula: Level = floor(sqrt(XP / 500)) + 1
        const newLevel = Math.floor(Math.sqrt(newXP / 500)) + 1;

        await supabase.from('profiles').update({ xp: newXP, level: newLevel }).eq('id', userId);

        if (newLevel > (profile.level || 1) && user?.id === userId) {
            notify('Level Up!', `You reached Level ${newLevel}!`, 'achievement');
        }
    } catch (e) { console.error(e); }
  };

  const uploadCourseImage = async (file: File): Promise<string> => {
    try {
        const fileExt = file.name.split('.').pop();
        const fileName = `${Math.random().toString(36).substring(2)}.${fileExt}`;
        const { error } = await supabase.storage.from('course-images').upload(fileName, file);
        if (error) throw error;
        const { data } = supabase.storage.from('course-images').getPublicUrl(fileName);
        return data.publicUrl;
    } catch (error: any) {
        throw new Error("Failed to upload image.");
    }
  };

  const addCourse = async (course: Course) => {
    const { data: courseData, error } = await supabase.from('courses').insert({
        title: course.title,
        code: course.code,
        description: course.description,
        professor_id: course.professorId, 
        image: course.image,
        university: course.university,
        price_full: course.priceFull,
        price_single: course.priceSingle
    }).select().single();

    if (error) throw new Error(error.message);

    if (courseData && course.lectures.length > 0) {
        const lectureInserts = course.lectures.map(l => ({
            course_id: courseData.id,
            title: l.title,
            date: l.date || new Date().toISOString(), 
            duration: l.duration
        }));
        await supabase.from('lectures').insert(lectureInserts);
    }
    await refreshData();
  };

  const addBooking = async (booking: Booking, pricePaid: number) => {
     const { error } = await supabase.from('bookings').insert({
       user_email: user?.email,
       course_id: booking.courseId, 
       course_title: booking.courseTitle,
       type: booking.type,
       status: 'pending',
       date: booking.date,
       price_paid: pricePaid
     });

     if (error) throw new Error(`Booking failed: ${error.message}`); 

     const xpAmount = booking.type === 'full' ? 500 : 200;
     if (user?.id) {
         await awardXP(user.id, xpAmount);
         if (refreshUser) refreshUser(); 
     }
     await refreshData();
  };

  const updateBookingStatus = async (id: string, status: 'approved' | 'rejected') => {
    const { data: bookingData } = await supabase.from('bookings').select('user_id, type').eq('id', id).single();
    const { error } = await supabase.from('bookings').update({ status }).eq('id', id);
    if (error) throw error;

    if (status === 'approved' && bookingData?.user_id) {
        const xpAmount = bookingData.type === 'full' ? 1000 : 300;
        await awardXP(bookingData.user_id, xpAmount);
    }
    await refreshData();
  };

  const updateLandingPage = async (data: Partial<LandingPageData>) => {
    const newData = { ...landingPageData, ...data };
    setLandingPageData(newData);
    await supabase.from('site_config').upsert({ key: 'landing_page', value: newData }, { onConflict: 'key' });
  };

  const updateUserRole = async (userId: string, role: UserRole) => {
      const { error } = await supabase.from('profiles').update({ role }).eq('id', userId);
      if (error) throw error;
      await refreshData();
  };

  const addProfessor = async (prof: Omit<Professor, 'id'>) => {
      const { error } = await supabase.from('professors').insert({
          name: prof.name,
          email: prof.email,
          custom_tag: prof.customTag,
          specialty: prof.specialty,
          avatar: prof.avatar,
          rating: prof.rating
      });
      if (error) throw new Error(error.message);
      await refreshData();
  }

  const updateProfessorDetails = async (prof: Professor) => {
      const { error } = await supabase.from('professors').update({
          name: prof.name,
          email: prof.email,
          custom_tag: prof.customTag,
          specialty: prof.specialty,
          avatar: prof.avatar,
          rating: prof.rating
      }).eq('id', prof.id);

      if (error) throw error;
      await refreshData();
  }

  const deleteProfessor = async (id: string) => {
      const { error } = await supabase.from('professors').delete().eq('id', id);
      if (error) throw error;
      await refreshData();
  }

  return (
    <DataContext.Provider value={{ 
      courses, addCourse, uploadCourseImage,
      bookings, addBooking, updateBookingStatus,
      landingPageData, updateLandingPage,
      users, professors, updateUserRole, 
      addProfessor, updateProfessorDetails, deleteProfessor,
      refreshData, myProfessorProfile
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => useContext(DataContext);

import React, { useState, useEffect, useRef } from 'react';
import { XPBar, AchievementBadge, AiTutor } from '../components/DashboardComponents';
import { Calendar as CalIcon, BookOpen, Clock, CheckCircle, XCircle, Users, Activity, BarChart2, Edit, Save, Plus, ChevronLeft, ChevronRight, Info, Bell, UploadCloud, Trash2, Settings, Lock, AlertTriangle, Shield, Search, Loader, UserCog, Mail, Tag } from 'lucide-react';
import { useAuth } from '../contexts/AuthContext';
import { useData } from '../contexts/DataContext';
import { useNotification } from '../contexts/NotificationContext';
import { useLanguage } from '../contexts/LanguageContext';
import { useNavigate, Navigate } from 'react-router-dom';
import { Booking, UserRole, Professor } from '../types';

// --- Improved Calendar Component ---
const SquareCalendar: React.FC<{ bookings: Booking[] }> = ({ bookings }) => {
    const [currentDate, setCurrentDate] = useState(new Date());
    const [selectedDate, setSelectedDate] = useState<Date | null>(null);

    const getDaysInMonth = (date: Date) => {
        const year = date.getFullYear();
        const month = date.getMonth();
        return new Date(year, month + 1, 0).getDate();
    };

    const getFirstDayOfMonth = (date: Date) => {
        const year = date.getFullYear();
        const month = date.getMonth();
        return new Date(year, month, 1).getDay(); // 0 = Sun, 1 = Mon...
    };

    const getStartOffset = (dayIndex: number) => dayIndex === 0 ? 6 : dayIndex - 1; 
    const daysInMonth = getDaysInMonth(currentDate);
    const startDay = getStartOffset(getFirstDayOfMonth(currentDate));
    const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

    const changeMonth = (offset: number) => {
        const newDate = new Date(currentDate.setMonth(currentDate.getMonth() + offset));
        setCurrentDate(new Date(newDate));
        setSelectedDate(null);
    };

    const isSameDay = (d1: Date, d2: Date) => d1.getDate() === d2.getDate() && d1.getMonth() === d2.getMonth() && d1.getFullYear() === d2.getFullYear();

    const getBookingsForDay = (day: number) => {
        return bookings.filter(b => {
            const bDate = new Date(b.date);
            return bDate.getDate() === day && bDate.getMonth() === currentDate.getMonth() && bDate.getFullYear() === currentDate.getFullYear() && b.status === 'approved'; 
        });
    };

    const renderCalendarDays = () => {
        const days = [];
        for (let i = 0; i < startDay; i++) {
            days.push(<div key={`empty-${i}`} className="h-24 bg-gray-50/30 border border-gray-100/50"></div>);
        }
        for (let i = 1; i <= daysInMonth; i++) {
            const dayBookings = getBookingsForDay(i);
            const isToday = isSameDay(new Date(), new Date(currentDate.getFullYear(), currentDate.getMonth(), i));
            const isSelected = selectedDate && selectedDate.getDate() === i;
            const approvedCount = dayBookings.length;

            days.push(
                <div 
                    key={i} 
                    onClick={() => setSelectedDate(new Date(currentDate.getFullYear(), currentDate.getMonth(), i))}
                    className={`h-24 border border-gray-100 p-2 cursor-pointer transition-all hover:bg-indigo-50 flex flex-col justify-between
                        ${isToday ? 'bg-indigo-50/50' : 'bg-white'}
                        ${isSelected ? 'ring-2 ring-indigo-500 z-10' : ''}
                    `}
                >
                    <div className="flex justify-between items-start">
                        <span className={`text-sm font-bold ${isToday ? 'text-indigo-600' : 'text-gray-700'}`}>{i}</span>
                        {approvedCount > 0 && (
                            <span className="w-2 h-2 rounded-full bg-green-500 shadow-sm shadow-green-200"></span>
                        )}
                    </div>
                    <div className="space-y-1 overflow-hidden">
                        {dayBookings.slice(0, 2).map((b, idx) => (
                            <div key={b.id} className="text-[10px] truncate bg-green-100 text-green-800 px-1 py-0.5 rounded border border-green-200">
                                {new Date(b.date).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})} - {b.courseTitle}
                            </div>
                        ))}
                    </div>
                </div>
            );
        }
        return days;
    };

    return (
        <div className="flex flex-col lg:flex-row gap-6 animate-fade-in-up">
            <div className="flex-1 bg-white rounded-2xl shadow-sm border border-gray-100 p-6">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="font-bold text-xl text-gray-900 flex items-center gap-2">
                        <CalIcon className="h-6 w-6 text-indigo-600" />
                        {monthNames[currentDate.getMonth()]} {currentDate.getFullYear()}
                    </h3>
                    <div className="flex gap-2">
                        <button onClick={() => changeMonth(-1)} className="p-2 hover:bg-gray-100 rounded-lg"><ChevronLeft className="h-5 w-5" /></button>
                        <button onClick={() => changeMonth(1)} className="p-2 hover:bg-gray-100 rounded-lg"><ChevronRight className="h-5 w-5" /></button>
                    </div>
                </div>
                <div className="grid grid-cols-7 text-center mb-2">
                    {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(day => <div key={day} className="text-xs font-bold text-gray-400 uppercase py-2">{day}</div>)}
                </div>
                <div className="grid grid-cols-7 bg-gray-200 border border-gray-200 gap-px overflow-hidden rounded-lg">
                    {renderCalendarDays()}
                </div>
            </div>
            <div className="w-full lg:w-80 bg-white rounded-2xl shadow-sm border border-gray-100 p-6 h-fit">
                <h4 className="font-bold text-gray-900 mb-4 border-b border-gray-100 pb-2">
                    {selectedDate ? selectedDate.toDateString() : "Select a date"}
                </h4>
                <div className="space-y-3 max-h-[400px] overflow-y-auto">
                    {!selectedDate ? (
                        <div className="text-center py-8 text-gray-400">
                            <Info className="h-8 w-8 mx-auto mb-2 opacity-50" />
                            <p className="text-sm">Click on a day to view details.</p>
                        </div>
                    ) : (
                         (() => {
                            const daysBookings = getBookingsForDay(selectedDate.getDate());
                            if (daysBookings.length === 0) return <p className="text-sm text-gray-500">No classes scheduled.</p>;
                            return daysBookings.map(b => (
                                <div key={b.id} className="p-3 bg-gray-50 rounded-xl border border-gray-100 hover:shadow-md transition-all">
                                    <div className="flex justify-between mb-1">
                                        <span className="font-bold text-indigo-700 text-xs uppercase">{new Date(b.date).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                                        <span className="text-[10px] bg-green-100 text-green-700 px-1.5 py-0.5 rounded-full font-bold">Confirmed</span>
                                    </div>
                                    <h5 className="font-bold text-gray-900 text-sm mb-1">{b.courseTitle}</h5>
                                    <p className="text-xs text-gray-500 flex items-center gap-1"><Users className="h-3 w-3" /> {b.userName || b.userEmail}</p>
                                </div>
                            ));
                         })()
                    )}
                </div>
            </div>
        </div>
    );
}

// --- Admin Booking Action Component ---
const BookingActionButtons: React.FC<{ bookingId: string, updateStatus: (id: string, status: 'approved'|'rejected') => Promise<void> }> = ({ bookingId, updateStatus }) => {
    const [loading, setLoading] = useState<'approved' | 'rejected' | null>(null);
    const { notify } = useNotification();
    const handleAction = async (status: 'approved' | 'rejected') => {
        setLoading(status);
        try {
            await updateStatus(bookingId, status);
            notify('Success', `Booking ${status}`, 'success');
        } catch(e: any) {
            console.error(e);
            notify('Error', `Failed to update: ${e.message || 'Unknown error'}`, 'info');
        }
        setLoading(null);
    }
    return (
        <div className="flex gap-2">
            <button onClick={() => handleAction('approved')} disabled={!!loading} className="p-1 hover:bg-green-100 text-green-600 rounded disabled:opacity-50">
                {loading === 'approved' ? <Loader className="h-5 w-5 animate-spin" /> : <CheckCircle className="h-5 w-5" />}
            </button>
            <button onClick={() => handleAction('rejected')} disabled={!!loading} className="p-1 hover:bg-red-100 text-red-600 rounded disabled:opacity-50">
                {loading === 'rejected' ? <Loader className="h-5 w-5 animate-spin" /> : <XCircle className="h-5 w-5" />}
            </button>
        </div>
    );
};

// --- Admin Professor Manager ---
const AdminProfessorManager: React.FC = () => {
    const { professors, updateProfessorDetails, addProfessor, deleteProfessor } = useData();
    const { notify } = useNotification();
    const [editingId, setEditingId] = useState<string | null>(null);
    const [editForm, setEditForm] = useState<Partial<Professor>>({});

    // Add New State
    const [isAdding, setIsAdding] = useState(false);
    const [newProf, setNewProf] = useState({ name: '', email: '', customTag: '', specialty: 'Professor', avatar: '', rating: 5.0 });

    const handleEdit = (prof: Professor) => { setEditingId(prof.id); setEditForm({ ...prof }); };

    const handleSave = async () => {
        if (!editingId || !editForm) return;
        try {
            await updateProfessorDetails(editForm as Professor);
            notify('Success', 'Professor details updated', 'success');
            setEditingId(null);
        } catch (e) { notify('Error', 'Failed to update details', 'info'); }
    };

    const handleDelete = async (id: string) => {
        if(window.confirm("Are you sure? This will delete the professor record.")) {
            try { await deleteProfessor(id); notify('Success', 'Professor deleted', 'success'); }
            catch (e) { notify('Error', 'Failed to delete', 'info'); }
        }
    }

    const generateTag = () => {
        if(!newProf.name) return;
        const cleanName = newProf.name.replace(/\s+/g, '');
        setNewProf({ ...newProf, customTag: `P${cleanName}` });
    }

    const handleAdd = async () => {
        if(!newProf.name || !newProf.email || !newProf.customTag) {
            notify('Error', 'Name, Email and Tag are required.', 'info');
            return;
        }
        try {
            await addProfessor({
                name: newProf.name,
                email: newProf.email,
                customTag: newProf.customTag,
                specialty: newProf.specialty,
                avatar: newProf.avatar || `https://ui-avatars.com/api/?name=${newProf.name}&background=random`,
                rating: newProf.rating
            });
            notify('Success', 'New Professor Added', 'success');
            setIsAdding(false);
            setNewProf({ name: '', email: '', customTag: '', specialty: 'Professor', avatar: '', rating: 5.0 });
        } catch (e: any) {
             notify('Error', e.message, 'info');
        }
    }

    return (
        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
             <div className="p-6 border-b border-gray-100 flex justify-between items-center">
                <h3 className="font-bold text-lg text-gray-900 flex items-center gap-2">
                    <UserCog className="h-5 w-5 text-indigo-600" /> Professor Management
                </h3>
                <button onClick={() => setIsAdding(!isAdding)} className="flex items-center gap-1 text-sm bg-indigo-50 text-indigo-600 px-3 py-1 rounded-lg font-bold hover:bg-indigo-100">
                    {isAdding ? 'Cancel' : <><Plus className="h-4 w-4" /> Add New</>}
                </button>
             </div>

             {isAdding && (
                 <div className="p-6 bg-indigo-50/50 border-b border-indigo-100 space-y-4">
                     <h4 className="font-bold text-indigo-900">Add New Professor</h4>
                     <div className="grid grid-cols-2 gap-4">
                         <input placeholder="Name" className="p-2 border rounded" value={newProf.name} onChange={e => setNewProf({...newProf, name: e.target.value})} />
                         <input placeholder="Email (for login mapping)" className="p-2 border rounded" value={newProf.email} onChange={e => setNewProf({...newProf, email: e.target.value})} />
                         <div className="flex gap-2">
                            <input placeholder="Tag (e.g. PNikola)" className="p-2 border rounded flex-1" value={newProf.customTag} onChange={e => setNewProf({...newProf, customTag: e.target.value})} />
                            <button onClick={generateTag} className="text-xs bg-gray-200 px-2 rounded hover:bg-gray-300">Gen</button>
                         </div>
                         <input placeholder="Specialty" className="p-2 border rounded" value={newProf.specialty} onChange={e => setNewProf({...newProf, specialty: e.target.value})} />
                     </div>
                     <button onClick={handleAdd} className="w-full bg-indigo-600 text-white p-2 rounded font-bold">Create Professor Record</button>
                 </div>
             )}

             <div className="overflow-x-auto">
                <table className="w-full text-left">
                    <thead className="bg-gray-50">
                        <tr>
                            <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Profile</th>
                            <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Map Email</th>
                            <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Custom Tag</th>
                            <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Specialty</th>
                            <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {professors.map(p => (
                            <tr key={p.id}>
                                <td className="px-6 py-4">
                                    <div className="font-bold text-gray-900">{p.name}</div>
                                    <div className="text-xs text-gray-400">ID: {p.id.substring(0,8)}...</div>
                                </td>
                                <td className="px-6 py-4">
                                    {editingId === p.id ? (
                                        <input className="border rounded p-1 text-sm w-full" value={editForm.email || ''} onChange={e => setEditForm({...editForm, email: e.target.value})} />
                                    ) : (
                                        <div className="flex items-center gap-1 text-sm text-gray-600"><Mail className="h-3 w-3" /> {p.email}</div>
                                    )}
                                </td>
                                <td className="px-6 py-4">
                                    {editingId === p.id ? (
                                        <input className="border rounded p-1 text-sm w-full" value={editForm.customTag || ''} onChange={e => setEditForm({...editForm, customTag: e.target.value})} />
                                    ) : (
                                        <div className="flex items-center gap-1 text-sm text-indigo-600 font-mono bg-indigo-50 px-2 py-0.5 rounded w-fit"><Tag className="h-3 w-3" /> {p.customTag}</div>
                                    )}
                                </td>
                                <td className="px-6 py-4">
                                    {editingId === p.id ? (
                                        <input className="border rounded p-1 text-sm w-full" value={editForm.specialty || ''} onChange={e => setEditForm({...editForm, specialty: e.target.value})} />
                                    ) : (
                                        <span className="text-sm text-gray-600">{p.specialty}</span>
                                    )}
                                </td>
                                <td className="px-6 py-4">
                                    {editingId === p.id ? (
                                        <div className="flex gap-2">
                                            <button onClick={handleSave} className="p-1 bg-green-100 text-green-700 rounded"><CheckCircle className="h-4 w-4" /></button>
                                            <button onClick={() => setEditingId(null)} className="p-1 bg-red-100 text-red-700 rounded"><XCircle className="h-4 w-4" /></button>
                                        </div>
                                    ) : (
                                        <div className="flex gap-2">
                                            <button onClick={() => handleEdit(p)} className="p-1 hover:bg-gray-100 rounded text-gray-500"><Edit className="h-4 w-4" /></button>
                                            <button onClick={() => handleDelete(p.id)} className="p-1 hover:bg-red-50 rounded text-red-400"><Trash2 className="h-4 w-4" /></button>
                                        </div>
                                    )}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
             </div>
        </div>
    );
};

// --- Admin Course Manager ---
const AdminCourseManager: React.FC = () => {
    const { addCourse, uploadCourseImage, professors } = useData();
    const { notify } = useNotification();
    const { t } = useLanguage();

    // Form State
    const [title, setTitle] = useState('');
    const [code, setCode] = useState('');
    const [description, setDescription] = useState('Online and group study available.');
    const [selectedProf, setSelectedProf] = useState('');
    const [university, setUniversity] = useState('FINKI'); 
    const [price, setPrice] = useState(6000);
    const [imageFile, setImageFile] = useState<File | null>(null);
    const [imagePreview, setImagePreview] = useState<string>('');
    const [isDragging, setIsDragging] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    // Default select
    useEffect(() => {
        if (professors.length > 0 && !selectedProf) {
            setSelectedProf(professors[0].id);
        }
    }, [professors]);

    // Module State
    const [lectures, setLectures] = useState<Array<{title: string, date: string, time: string}>>([]);
    const [newModTitle, setNewModTitle] = useState('');
    const [newModDate, setNewModDate] = useState('');
    const [newModHour, setNewModHour] = useState('09');
    const [newModMinute, setNewModMinute] = useState('00');

    const handleDragOver = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(true); };
    const handleDragLeave = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(false); };
    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault(); setIsDragging(false);
        const file = e.dataTransfer.files[0];
        if (file && file.type.startsWith('image/')) { setImageFile(file); setImagePreview(URL.createObjectURL(file)); }
    };
    const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) { setImageFile(e.target.files[0]); setImagePreview(URL.createObjectURL(e.target.files[0])); }
    };

    const addModule = () => {
        if (!newModTitle || !newModDate) {
            notify('Error', 'Please fill all module fields', 'info');
            return;
        }
        const timeString = `${newModHour}:${newModMinute}`;
        setLectures([...lectures, { title: newModTitle, date: newModDate, time: timeString }]);
        setNewModTitle('');
        setNewModDate('');
        setNewModHour('09');
        setNewModMinute('00');
    };

    const removeLecture = (index: number) => {
        setLectures(lectures.filter((_, i) => i !== index));
    };

    const handleAddCourse = async () => {
        if(!title || !code || !selectedProf || lectures.length === 0) {
            notify('Error', 'Missing required fields or modules', 'info');
            return;
        }
        setIsSubmitting(true);
        const finalLectures = lectures.map((l, i) => ({
            id: `l-new-${Date.now()}-${i}`,
            title: l.title,
            date: new Date(`${l.date}T${l.time}`).toISOString(),
            duration: 90,
        }));

        try {
            // 1. Handle Image Upload
            let finalImageUrl = imagePreview;
            if (imageFile) {
                finalImageUrl = await uploadCourseImage(imageFile);
            } else if (!imagePreview) {
                finalImageUrl = "https://picsum.photos/800/400?random=" + Math.random();
            }

            // 2. Add Course
            await addCourse({
                id: `c-${Date.now()}`,
                title, code, description, professorId: selectedProf,
                university: university,
                image: finalImageUrl,
                priceFull: Number(price), priceSingle: 750, lectures: finalLectures
            });
            notify('Course Added', `${title} is live!`, 'success');
            setTitle(''); setCode(''); setLectures([]); setImagePreview(''); setImageFile(null);
        } catch (e: any) {
            notify('Error', e.message || 'Failed to add course.', 'info');
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6">
            <h3 className="font-bold text-lg text-gray-900 mb-6 flex items-center gap-2">
                <Plus className="h-5 w-5 text-indigo-600" /> {t('createCourse')}
            </h3>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                <div className="space-y-4">
                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">{t('courseTitle')}</label>
                        <input className="w-full p-2 border rounded-lg" value={title} onChange={e => setTitle(e.target.value)} />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                             <label className="block text-xs font-bold text-gray-500 uppercase mb-1">{t('courseCode')}</label>
                             <input className="w-full p-2 border rounded-lg" value={code} onChange={e => setCode(e.target.value)} />
                        </div>
                        <div>
                             <label className="block text-xs font-bold text-gray-500 uppercase mb-1">{t('priceMkd')}</label>
                             <input type="number" className="w-full p-2 border rounded-lg" value={price} onChange={e => setPrice(Number(e.target.value))} />
                        </div>
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">University</label>
                        <input 
                            list="uni-list"
                            className="w-full p-2 border rounded-lg bg-white" 
                            value={university} 
                            onChange={e => setUniversity(e.target.value)}
                            placeholder="Select or type university..."
                        />
                        <datalist id="uni-list">
                            <option value="FINKI" />
                            <option value="UKIM" />
                            <option value="FON" />
                            <option value="American College" />
                            <option value="Medical Faculty" />
                        </datalist>
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">{t('assignProf')}</label>
                        <select className="w-full p-2 border rounded-lg bg-white" value={selectedProf} onChange={e => setSelectedProf(e.target.value)}>
                            {professors.map(p => <option key={p.id} value={p.id}>{p.name} ({p.customTag})</option>)}
                        </select>
                    </div>
                     <div>
                         <label className="block text-xs font-bold text-gray-500 uppercase mb-1">{t('desc')}</label>
                         <textarea rows={3} className="w-full p-2 border rounded-lg" value={description} onChange={e => setDescription(e.target.value)} />
                    </div>
                </div>

                <div className="space-y-4">
                     <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">{t('coverImg')}</label>
                        <div 
                            onDragOver={handleDragOver} onDragLeave={handleDragLeave} onDrop={handleDrop}
                            onClick={() => fileInputRef.current?.click()}
                            className={`border-2 border-dashed rounded-xl p-4 flex flex-col items-center justify-center cursor-pointer transition-colors h-32 ${isDragging ? 'border-indigo-500 bg-indigo-50' : 'border-gray-300 hover:bg-gray-50'} ${imagePreview ? 'p-0 overflow-hidden' : ''}`}
                        >
                            {imagePreview ? (
                                <img src={imagePreview} alt="Preview" className="w-full h-full object-cover" />
                            ) : (
                                <>
                                    <UploadCloud className="h-8 w-8 text-gray-400 mb-2" />
                                    <p className="text-xs text-gray-500 text-center">{t('uploadText')}</p>
                                </>
                            )}
                            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileInput} />
                        </div>
                     </div>

                     <div className="bg-gray-50 rounded-xl p-4 border border-gray-100">
                        <label className="block text-xs font-bold text-gray-500 uppercase mb-3 flex justify-between">
                            <span>{t('modules')}</span>
                            <span className="text-indigo-600">{lectures.length}</span>
                        </label>
                        <div className="space-y-2 mb-3 max-h-40 overflow-y-auto">
                            {lectures.map((l, i) => (
                                <div key={i} className="flex justify-between items-center bg-white p-2 rounded border border-gray-100 text-sm">
                                    <div className="truncate flex-1">
                                        <span className="font-bold block text-gray-900">{l.title}</span>
                                        <span className="text-xs text-gray-500">{l.date} @ {l.time}</span>
                                    </div>
                                    <button onClick={() => removeLecture(i)} className="text-red-400 hover:text-red-600 p-1"><Trash2 className="h-4 w-4" /></button>
                                </div>
                            ))}
                        </div>

                        <div className="grid grid-cols-1 gap-2">
                             <input placeholder={t('moduleTitle')} className="w-full p-2 border rounded text-sm" value={newModTitle} onChange={e => setNewModTitle(e.target.value)} />
                             <div className="flex gap-2">
                                 <input type="date" className="flex-1 p-2 border rounded text-sm" value={newModDate} onChange={e => setNewModDate(e.target.value)} />
                                 <select className="w-16 p-2 border rounded text-sm bg-white" value={newModHour} onChange={e => setNewModHour(e.target.value)}>
                                     {Array.from({length: 24}).map((_, i) => {
                                         const h = i.toString().padStart(2, '0');
                                         return <option key={h} value={h}>{h}</option>;
                                     })}
                                 </select>
                                 <span className="self-center font-bold text-gray-400">:</span>
                                 <select className="w-16 p-2 border rounded text-sm bg-white" value={newModMinute} onChange={e => setNewModMinute(e.target.value)}>
                                     {['00', '15', '30', '45'].map(m => <option key={m} value={m}>{m}</option>)}
                                 </select>

                                 <button onClick={addModule} className="bg-indigo-600 text-white p-2 rounded hover:bg-indigo-700">
                                     <Plus className="h-4 w-4" />
                                 </button>
                             </div>
                        </div>
                     </div>
                </div>
            </div>

            <button 
                onClick={handleAddCourse} 
                disabled={isSubmitting}
                className="w-full bg-green-600 text-white px-4 py-3 rounded-lg hover:bg-green-700 font-bold shadow-lg shadow-green-200 disabled:opacity-50 flex justify-center items-center gap-2"
            >
                {isSubmitting && <Loader className="animate-spin h-5 w-5" />}
                {t('publishCourse')}
            </button>
        </div>
    )
}

