-- FINKI Tutors - Schema Update & Fixes
-- ⚠️ WARNING: THIS WILL DROP EXISTING TABLES TO ENSURE EVERYTHING WORKS ⚠️

-- 1. CLEANUP
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
DROP FUNCTION IF EXISTS public.handle_new_user() CASCADE;
DROP FUNCTION IF EXISTS public.is_admin() CASCADE;
DROP FUNCTION IF EXISTS public.link_teacher_to_course(text, text, text) CASCADE;

DROP TABLE IF EXISTS public.bookings CASCADE;
DROP TABLE IF EXISTS public.lectures CASCADE;
DROP TABLE IF EXISTS public.courses CASCADE;
DROP TABLE IF EXISTS public.achievements CASCADE;
DROP TABLE IF EXISTS public.site_config CASCADE;
DROP TABLE IF EXISTS public.professors CASCADE; 
DROP TABLE IF EXISTS public.profiles CASCADE;

-- Drop types
DROP TYPE IF EXISTS public.booking_type_enum CASCADE;
DROP TYPE IF EXISTS public.booking_status CASCADE;
DROP TYPE IF EXISTS public.user_role CASCADE;

-- 2. EXTENSIONS
create extension if not exists "uuid-ossp";

-- 3. ENUMS
create type public.user_role as enum ('student', 'teacher', 'admin');
create type public.booking_status as enum ('pending', 'approved', 'rejected');
create type public.booking_type_enum as enum ('single', 'full');

-- 4. PROFILES
create table public.profiles (
  id uuid references auth.users on delete cascade primary key,
  email text unique not null,
  full_name text,
  role public.user_role default 'student', 
  xp integer default 0,
  level integer default 1,
  credits integer default 0,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- 4.1 PROFESSORS (New Separate Table)
-- We decouple ID from profiles.id so Admin can create professors before they sign up.
-- Link happens via EMAIL.
create table public.professors (
  id uuid default uuid_generate_v4() primary key,
  custom_tag text unique, -- e.g. "PNikolaJankoski"
  email text unique not null, -- The link to the User
  name text not null,
  specialty text default 'Professor',
  avatar text default 'https://ui-avatars.com/api/?name=Professor&background=random',
  rating numeric(3,1) default 5.0,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- 5. COURSES
create table public.courses (
  id uuid default uuid_generate_v4() primary key,
  title text not null,
  code text not null,
  description text,
  professor_id uuid references public.professors(id) on delete set null, 
  image text,
  university text default 'FINKI',
  price_full integer not null default 6000,
  price_single integer not null default 750,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- 6. LECTURES
create table public.lectures (
  id uuid default uuid_generate_v4() primary key,
  course_id uuid references public.courses(id) on delete cascade,
  title text not null,
  date timestamp with time zone default now() not null, 
  duration integer default 90,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- 7. BOOKINGS
create table public.bookings (
  id uuid default uuid_generate_v4() primary key,
  user_id uuid default auth.uid() references public.profiles(id) on delete cascade,
  user_email text, 
  course_id uuid references public.courses(id) on delete cascade,
  course_title text,
  type public.booking_type_enum not null,
  status public.booking_status default 'pending',
  date timestamp with time zone not null,
  price_paid integer default 0, -- Store actual price paid (in case of discounts)
