-- 13. ADMIN HELPER FUNCTION (For Manual Linking in Supabase)
-- Usage in SQL Editor: select link_teacher_to_course('teacher@email.com', 'Professor Name', 'COURSE-CODE');
create or replace function public.link_teacher_to_course(
    teacher_email text, 
    teacher_name text, 
    course_code text
) returns void as $$
declare
    new_prof_id uuid;
begin
    -- 1. Ensure User is a Teacher in Profiles (if user exists)
    update public.profiles 
    set role = 'teacher' 
    where email = teacher_email;

    -- 2. Create or Get Professor ID based on email
    -- We use ON CONFLICT to avoid duplicates if you run this multiple times
    insert into public.professors (email, name, custom_tag)
    values (
        teacher_email, 
        teacher_name, 
        'P' || regexp_replace(teacher_name, '\s+', '', 'g') || floor(random() * 100)::text
    )
    on conflict (email) do update 
    set name = excluded.name -- Update name if it changed
    returning id into new_prof_id;

    -- If the insert didn't return (because of conflict update where no change needed), get the ID manually
    if new_prof_id is null then
        select id into new_prof_id from public.professors where email = teacher_email;
    end if;

    -- 3. Update Course to point to this Professor
    update public.courses
    set professor_id = new_prof_id
    where code = course_code;

end;
$$ language plpgsql security definer set search_path = public;

