const BookingActionButtons: React.FC<{ bookingId: string, updateStatus: (id: string, status: 'approved'|'rejected') => Promise<void> }> = ({ bookingId, updateStatus }) => {
    const [loading, setLoading] = useState<'approved' | 'rejected' | null>(null);
    const { notify } = useNotification();
    const handleAction = async (status: 'approved' | 'rejected') => {
        setLoading(status);
        try {
            await updateStatus(bookingId, status);
            notify('Success', `Booking ${status}`, 'success');
        } catch(e: any) {
            console.error(e);
            notify('Error', `Failed to update: ${e.message || 'Unknown error'}`, 'info');
        }
        setLoading(null);
    }
    return (
        <div className="flex gap-2">
            <button onClick={() => handleAction('approved')} disabled={!!loading} className="p-1 hover:bg-green-100 text-green-600 rounded disabled:opacity-50">
                {loading === 'approved' ? <Loader className="h-5 w-5 animate-spin" /> : <CheckCircle className="h-5 w-5" />}
            </button>
            <button onClick={() => handleAction('rejected')} disabled={!!loading} className="p-1 hover:bg-red-100 text-red-600 rounded disabled:opacity-50">
                {loading === 'rejected' ? <Loader className="h-5 w-5 animate-spin" /> : <XCircle className="h-5 w-5" />}
            </button>
        </div>
    );
};

// --- Admin Professor Manager ---
const AdminProfessorManager: React.FC = () => {
    const { professors, users, updateProfessorDetails, addProfessor, deleteProfessor } = useData();
    const { notify } = useNotification();
    const [editingId, setEditingId] = useState<string | null>(null);
    const [editForm, setEditForm] = useState<Partial<Professor>>({});

    // Add New State
    const [isAdding, setIsAdding] = useState(false);
    const [newProf, setNewProf] = useState({ name: '', email: '', customTag: '', specialty: 'Professor', avatar: '', rating: 5.0 });

    const handleEdit = (prof: Professor) => { setEditingId(prof.id); setEditForm({ ...prof }); };

    const handleSave = async () => {
        if (!editingId || !editForm) return;
        try {
            await updateProfessorDetails(editForm as Professor);
            notify('Success', 'Professor details updated', 'success');
            setEditingId(null);
        } catch (e) { notify('Error', 'Failed to update details', 'info'); }
    };

    const handleDelete = async (id: string) => {
        if(window.confirm("Are you sure? This will delete the professor record.")) {
            try { await deleteProfessor(id); notify('Success', 'Professor deleted', 'success'); }
            catch (e) { notify('Error', 'Failed to delete', 'info'); }
        }
    }

    const generateTag = () => {
        if(!newProf.name) return;
        const cleanName = newProf.name.replace(/\s+/g, '');
        setNewProf({ ...newProf, customTag: `P${cleanName}` });
    }

    const handleAdd = async () => {
        if(!newProf.name || !newProf.email || !newProf.customTag) {
            notify('Error', 'Name, Email and Tag are required.', 'info');
            return;
        }
        try {
            await addProfessor({
                name: newProf.name,
                email: newProf.email,
                customTag: newProf.customTag,
                specialty: newProf.specialty,
                avatar: newProf.avatar || `https://ui-avatars.com/api/?name=${newProf.name}&background=random`,
                rating: newProf.rating
            });
            notify('Success', 'New Professor Added', 'success');
            setIsAdding(false);
            setNewProf({ name: '', email: '', customTag: '', specialty: 'Professor', avatar: '', rating: 5.0 });
        } catch (e: any) {
             notify('Error', e.message, 'info');
        }
    }

    return (
        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
             <div className="p-6 border-b border-gray-100 flex justify-between items-center">
                <h3 className="font-bold text-lg text-gray-900 flex items-center gap-2">
                    <UserCog className="h-5 w-5 text-indigo-600" /> Professor Management
                </h3>
